import { createCanvas } from "./CanvasUtils";
import { isChaosStyle } from "../systems/vfx/utils";

// Dimensions
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: 'GLOW' | 'SOLID' | 'OUTLINE' | 'NOISE' | 'BLAST' | 'SHARD' | 'CHIP' | 'CRACKS' | 'LIQUID', color: string): HTMLCanvasElement {
        const key = `${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;

        ctx.translate(CENTER, CENTER);

        if (type === 'GLOW') {
            const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.2, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            this.pathHex(ctx, r);
            ctx.fill();
        } 
        else if (type === 'SOLID') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.9);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 2;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'OUTLINE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            this.pathHex(ctx, r * 0.8);
            ctx.stroke();
        }
        else if (type === 'NOISE') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r);
            ctx.fill();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            for(let i=0; i<20; i++) {
                const rx = (Math.random() - 0.5) * r * 1.5;
                const ry = (Math.random() - 0.5) * r * 1.5;
                const rs = Math.random() * r * 0.4;
                ctx.beginPath(); ctx.arc(rx, ry, rs, 0, Math.PI*2); ctx.fill();
            }
        }
        else if (type === 'BLAST') {
            const isChaos = isChaosStyle(color);
            if (isChaos) {
                ctx.fillStyle = color;
                ctx.beginPath();
                for(let i=0; i<12; i++) {
                    const angle = (i / 12) * Math.PI * 2;
                    const rad = (i % 2 === 0) ? r : r * 0.4;
                    const x = Math.cos(angle) * rad;
                    const y = Math.sin(angle) * rad;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
            } else {
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#ffffff');        
                grad.addColorStop(0.3, color);          
                grad.addColorStop(1, 'transparent');  
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            }
        }
        else if (type === 'CHIP') {
            // Simple Square Chip
            ctx.fillStyle = color;
            ctx.fillRect(-r/2, -r/2, r, r);
        }
        else if (type === 'SHARD') {
            // Triangular Shard
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(r, 0);
            ctx.lineTo(-r * 0.5, r * 0.4);
            ctx.lineTo(-r * 0.5, -r * 0.4);
            ctx.fill();
            // Subtle highlight
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 4;
            ctx.stroke();
        }
        else if (type === 'CRACKS') {
            // Pre-baked jagged fractal lines for Magma/Ground effects
            // This replaces the expensive per-frame drawing
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';

            const branches = 4;
            for(let i=0; i<branches; i++) {
                const angle = (i / branches) * Math.PI * 2 + (Math.random()*0.5);
                ctx.beginPath();
                ctx.moveTo(0, 0);

                let cx = 0, cy = 0;
                const len = r * 0.9;
                const steps = 3;
                for(let j=0; j<steps; j++) {
                    const stepLen = len / steps;
                    // Deterministic randomness for baking
                    const r1 = Math.sin(i * 99 + j * 33);
                    const r2 = Math.cos(i * 55 + j * 77);

                    cx += Math.cos(angle) * stepLen + r1 * 8;
                    cy += Math.sin(angle) * stepLen + r2 * 8;
                    ctx.lineTo(cx, cy);
                }
                ctx.stroke();
            }
            // Glowing Core
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI*2); ctx.fill();
        }
        else if (type === 'LIQUID') {
            // Pre-baked liquid pool to save per-frame drawing costs
            const poolR = r * 0.85;

            // Base fluid
            ctx.fillStyle = color;
            ctx.beginPath(); 
            ctx.arc(0, 0, poolR, 0, Math.PI * 2); 
            ctx.fill();

            // Inner depth (Darker center)
            ctx.globalCompositeOperation = 'multiply';
            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath();
            ctx.arc(0, 0, poolR * 0.7, 0, Math.PI * 2);
            ctx.fill();

            // Rim Highlight
            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = 'rgba(255,255,255,0.2)';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(0, 0, poolR - 2, 0, Math.PI * 2);
            ctx.stroke();
        }

        return canvas;
    }

    private pathHex(ctx: CanvasRenderingContext2D, r: number) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = i * Math.PI / 3;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
    }

    generateGlowOrb(color: string, size: number = 64): HTMLCanvasElement {
        return this.getTexture('GLOW', color);
    }

    generateFogCloud(color: string): HTMLCanvasElement {
        return this.getTexture('GLOW', color); 
    }

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        return this.createLegacyProjectile(visual, color);
    }

    generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('BLAST', color);
    }

    // New Accessor for Cracks
    generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    private createLegacyProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 64);
        const cx = 48, cy = 32;
        ctx.shadowColor = color; ctx.shadowBlur = 10;
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';

        if (visual === 'ARROW') {
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8); ctx.fill();
        } else {
            const grad = ctx.createLinearGradient(0, 0, 96, 0);
            grad.addColorStop(0, 'transparent'); grad.addColorStop(0.5, color); grad.addColorStop(1, '#fff');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2); ctx.fill();
        }
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

const VISIBLE_FACES = [0, 1, 5]; 

export const SurfaceAssets = {

    pathHex(ctx: CanvasRenderingContext2D, x: number, y: number, scale: number = 1.0) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const c = HEX_CORNERS[i];
            if (i === 0) ctx.moveTo(x + c.x * scale, y + c.y * scale);
            else ctx.lineTo(x + c.x * scale, y + c.y * scale);
        }
        ctx.closePath();
    },

    // 1. LIQUID SURFACE (Blood, Lava, Acid)
    // PERFORMANCE OVERHAUL: Now uses cached texture + simple scaling instead of procedural noise paths
    drawLiquidSurface(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        const texture = VFXFactory.getTexture('LIQUID', color);
        // Texture size is 128, Hex size is approx 72.
        const scaleFactor = (HEX_SIZE * 2.2) / 128;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        // Simulate "breathing" liquid via simple scaling instead of recalculating 12 vertex points
        const breath = 1.0 + Math.sin(time * 2.5) * 0.05;
        const finalScale = scaleFactor * breath;

        ctx.scale(finalScale, finalScale);

        // Draw cached pool
        ctx.globalAlpha = 0.9 * intensity;
        ctx.drawImage(texture, -64, -64, 128, 128);

        // Simple cheap highlight bubble (keeps it feeling alive)
        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.5 * intensity;

        const bubbleX = Math.sin(time) * 20;
        const bubbleY = Math.cos(time * 0.8) * 15;

        ctx.beginPath();
        ctx.ellipse(bubbleX, bubbleY, 8, 3, 0, 0, Math.PI*2);
        ctx.fill();

        ctx.restore();
    },

    // 2. VOLUMETRIC FOG (Poison, Smoke)
    // OPTIMIZED: Uses cached GLOW texture instead of real-time gradients
    drawVolumetricFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const puffTexture = VFXFactory.getTexture('GLOW', color);
        const textureSize = puffTexture.width;
        const halfSize = textureSize / 2;

        ctx.save();
        ctx.translate(x, y);

        ctx.globalCompositeOperation = 'screen'; 
        ctx.globalAlpha = 0.2; 

        // Create cloud puffs
        const puffs = 4; // Reduced from 5
        for(let i=0; i<puffs; i++) {
            // Orbiting motion logic preserved
            const angle = time * 0.5 + i * (Math.PI * 2 / puffs);
            const dist = Math.sin(time * 0.2 + i) * 15;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist * ISO_SCALE_Y - 15; 

            const scale = (1.0 + Math.sin(time + i) * 0.2) * 0.5; // Scale relative to texture size
            const size = textureSize * scale;

            // Draw Cached Texture
            ctx.drawImage(puffTexture, px - size/2, py - size/2, size, size);
        }

        // Ground Haze (Base layer) using same texture stretched
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalAlpha = 0.15;
        const baseSize = HEX_SIZE * 2.5;
        ctx.drawImage(puffTexture, -baseSize/2, -baseSize/2, baseSize, baseSize);

        ctx.restore();
    },

    // 3. GROUND CRACKS (Smash, Earthquake)
    // OPTIMIZED: Uses pre-baked CRACKS texture instead of procedural drawing
    drawGroundCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'lighter'; 
        ctx.globalAlpha = intensity;

        // Slight rotation for variety based on position (pseudo-random)
        // using x coordinate as seed to keep it static per tile
        const staticRot = (x % 3) * (Math.PI / 3);
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -half, -half, size, size);

        ctx.restore();
    },

    // Original Extruded Hex (Kept for basic fields/walls/indicators)
    drawExtrudedHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number,
        isHollow: boolean = false
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity * 0.6;

        for (const i of VISIBLE_FACES) {
            const idx1 = i;
            const idx2 = (i + 1) % 6;

            const c1 = HEX_CORNERS[idx1];
            const c2 = HEX_CORNERS[idx2];

            let shade = 1.0;
            if (i === 5) shade = 0.7; 
            if (i === 0) shade = 0.5; 
            if (i === 1) shade = 0.9; 

            // NOTE: Gradient here is still needed for depth, but it's only 3 per hex
            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c2.x, topY + c2.y);
            ctx.lineTo(x + c2.x, bottomY + c2.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.closePath();

            const oldAlpha = ctx.globalAlpha;
            ctx.globalAlpha = oldAlpha * shade;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.8;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.stroke();

            ctx.globalAlpha = oldAlpha;
        }

        if (!isHollow) {
            ctx.globalAlpha = opacity;
            ctx.fillStyle = color;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = opacity * 0.5;
            this.pathHex(ctx, x, topY, 0.8);
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        this.pathHex(ctx, x, topY, 1.0);
        ctx.stroke();

        ctx.restore();
    },

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        // Optimized Seed: Use bitwise ops for speed
        const seed = ((q * 73856093) ^ (r * 19349663)) / 2147483647; 
        const normalizedSeed = Math.abs(seed - Math.floor(seed));

        if (type === 'MAGMA') {
            if (normalizedSeed > 0.5) {
                // Using the optimized drawGroundCracks which now uses cache
                this.drawGroundCracks(ctx, cx, cy, '#ef4444', 0.6);
            }
        } else if (type === 'VOID') {
            // VOID texture logic remains simple rects, but use context save/restore carefully
            if (normalizedSeed > 0.7) {
                ctx.save();
                ctx.fillStyle = '#38bdf8';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(cx - 2, cy - 2, 4, 4);

                ctx.strokeStyle = color;
                ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+10, cy-5); ctx.stroke();
                ctx.restore();
            }
        }
    },

    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        const r = HEX_SIZE * 0.8 * progress; 
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();
        ctx.rotate(t * 2);
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI/4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, Math.PI + Math.PI/4); ctx.stroke();
        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { isChaosStyle } from "../systems/vfx/utils";

// Dimensions
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: 'GLOW' | 'SOLID' | 'OUTLINE' | 'NOISE' | 'BLAST' | 'SHARD' | 'CHIP' | 'CRACKS' | 'LIQUID', color: string): HTMLCanvasElement {
        const key = `${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;

        ctx.translate(CENTER, CENTER);

        if (type === 'GLOW') {
            const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.2, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            this.pathHex(ctx, r);
            ctx.fill();
        } 
        else if (type === 'SOLID') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.9);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 2;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'OUTLINE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            this.pathHex(ctx, r * 0.8);
            ctx.stroke();
        }
        else if (type === 'NOISE') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r);
            ctx.fill();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            for(let i=0; i<20; i++) {
                const rx = (Math.random() - 0.5) * r * 1.5;
                const ry = (Math.random() - 0.5) * r * 1.5;
                const rs = Math.random() * r * 0.4;
                ctx.beginPath(); ctx.arc(rx, ry, rs, 0, Math.PI*2); ctx.fill();
            }
        }
        else if (type === 'BLAST') {
            const isChaos = isChaosStyle(color);
            if (isChaos) {
                ctx.fillStyle = color;
                ctx.beginPath();
                for(let i=0; i<12; i++) {
                    const angle = (i / 12) * Math.PI * 2;
                    const rad = (i % 2 === 0) ? r : r * 0.4;
                    const x = Math.cos(angle) * rad;
                    const y = Math.sin(angle) * rad;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
            } else {
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#ffffff');        
                grad.addColorStop(0.3, color);          
                grad.addColorStop(1, 'transparent');  
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            }
        }
        else if (type === 'CHIP') {
            // Simple Square Chip
            ctx.fillStyle = color;
            ctx.fillRect(-r/2, -r/2, r, r);
        }
        else if (type === 'SHARD') {
            // Triangular Shard
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(r, 0);
            ctx.lineTo(-r * 0.5, r * 0.4);
            ctx.lineTo(-r * 0.5, -r * 0.4);
            ctx.fill();
            // Subtle highlight
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 4;
            ctx.stroke();
        }
        else if (type === 'CRACKS') {
            // Pre-baked jagged fractal lines for Magma/Ground effects
            // This replaces the expensive per-frame drawing
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';

            const branches = 4;
            for(let i=0; i<branches; i++) {
                const angle = (i / branches) * Math.PI * 2 + (Math.random()*0.5);
                ctx.beginPath();
                ctx.moveTo(0, 0);

                let cx = 0, cy = 0;
                const len = r * 0.9;
                const steps = 3;
                for(let j=0; j<steps; j++) {
                    const stepLen = len / steps;
                    // Deterministic randomness for baking
                    const r1 = Math.sin(i * 99 + j * 33);
                    const r2 = Math.cos(i * 55 + j * 77);

                    cx += Math.cos(angle) * stepLen + r1 * 8;
                    cy += Math.sin(angle) * stepLen + r2 * 8;
                    ctx.lineTo(cx, cy);
                }
                ctx.stroke();
            }
            // Glowing Core
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI*2); ctx.fill();
        }
        else if (type === 'LIQUID') {
            // Updated to avoid trypophobia (holes/eyes)
            // Use a large circular gradient that fills mostly solid
            const poolR = r * 0.95;

            // 1. Solid Base with Gradient (Center hot)
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, poolR);
            grad.addColorStop(0, color); // Center
            grad.addColorStop(0.8, color);
            grad.addColorStop(1, 'transparent'); // Soft fade at very edge to blend

            ctx.fillStyle = grad;
            ctx.beginPath(); 
            ctx.arc(0, 0, poolR, 0, Math.PI * 2); 
            ctx.fill();

            // 2. Texture: Organic blobs (Crust) instead of concentric rings
            ctx.globalCompositeOperation = 'multiply';
            ctx.fillStyle = 'rgba(0,0,0,0.3)';

            for(let i=0; i<5; i++) {
                const a = Math.random() * Math.PI * 2;
                const d = Math.random() * poolR * 0.5;
                const s = poolR * (0.1 + Math.random() * 0.2);

                ctx.beginPath();
                ctx.ellipse(Math.cos(a)*d, Math.sin(a)*d, s, s*0.6, Math.random()*Math.PI, 0, Math.PI*2);
                ctx.fill();
            }

            // 3. Subtle Heat Overlay (No sharp rim)
            ctx.globalCompositeOperation = 'screen';
            ctx.fillStyle = 'rgba(255,255,255,0.1)';
            ctx.beginPath();
            ctx.arc(0, 0, poolR * 0.5, 0, Math.PI * 2);
            ctx.fill();
        }

        return canvas;
    }

    private pathHex(ctx: CanvasRenderingContext2D, r: number) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = i * Math.PI / 3;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
    }

    generateGlowOrb(color: string, size: number = 64): HTMLCanvasElement {
        return this.getTexture('GLOW', color);
    }

    generateFogCloud(color: string): HTMLCanvasElement {
        return this.getTexture('GLOW', color); 
    }

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        return this.createLegacyProjectile(visual, color);
    }

    generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('BLAST', color);
    }

    // New Accessor for Cracks
    generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    private createLegacyProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 64);
        const cx = 48, cy = 32;
        ctx.shadowColor = color; ctx.shadowBlur = 10;
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';

        if (visual === 'ARROW') {
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8); ctx.fill();
        } else {
            const grad = ctx.createLinearGradient(0, 0, 96, 0);
            grad.addColorStop(0, 'transparent'); grad.addColorStop(0.5, color); grad.addColorStop(1, '#fff');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2); ctx.fill();
        }
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

const VISIBLE_FACES = [0, 1, 5]; 

export const SurfaceAssets = {

    pathHex(ctx: CanvasRenderingContext2D, x: number, y: number, scale: number = 1.0) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const c = HEX_CORNERS[i];
            if (i === 0) ctx.moveTo(x + c.x * scale, y + c.y * scale);
            else ctx.lineTo(x + c.x * scale, y + c.y * scale);
        }
        ctx.closePath();
    },

    // 1. LIQUID SURFACE (Blood, Lava, Acid)
    // PERFORMANCE OVERHAUL: Now uses cached texture + simple scaling instead of procedural noise paths
    drawLiquidSurface(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        const texture = VFXFactory.getTexture('LIQUID', color);
        // Texture size is 128, Hex size is approx 72.
        const scaleFactor = (HEX_SIZE * 2.2) / 128;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        // Simulate "breathing" liquid via simple scaling
        // Reduced amplitude to avoid creating large gaps (trypophobia fix)
        const breath = 1.0 + Math.sin(time * 1.5) * 0.03; 
        const finalScale = scaleFactor * breath;

        ctx.scale(finalScale, finalScale);

        // Draw cached pool
        ctx.globalAlpha = 0.9 * intensity;
        ctx.drawImage(texture, -64, -64, 128, 128);

        // REMOVED: Moving bubble which created "crawling insect" look on dense grids

        ctx.restore();
    },

    // 2. VOLUMETRIC FOG (Poison, Smoke)
    // OPTIMIZED: Uses cached GLOW texture instead of real-time gradients
    drawVolumetricFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const puffTexture = VFXFactory.getTexture('GLOW', color);
        const textureSize = puffTexture.width;
        const halfSize = textureSize / 2;

        ctx.save();
        ctx.translate(x, y);

        ctx.globalCompositeOperation = 'screen'; 
        ctx.globalAlpha = 0.2; 

        // Create cloud puffs
        const puffs = 4; // Reduced from 5
        for(let i=0; i<puffs; i++) {
            // Orbiting motion logic preserved
            const angle = time * 0.5 + i * (Math.PI * 2 / puffs);
            const dist = Math.sin(time * 0.2 + i) * 15;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist * ISO_SCALE_Y - 15; 

            const scale = (1.0 + Math.sin(time + i) * 0.2) * 0.5; // Scale relative to texture size
            const size = textureSize * scale;

            // Draw Cached Texture
            ctx.drawImage(puffTexture, px - size/2, py - size/2, size, size);
        }

        // Ground Haze (Base layer) using same texture stretched
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalAlpha = 0.15;
        const baseSize = HEX_SIZE * 2.5;
        ctx.drawImage(puffTexture, -baseSize/2, -baseSize/2, baseSize, baseSize);

        ctx.restore();
    },

    // 3. GROUND CRACKS (Smash, Earthquake)
    // OPTIMIZED: Uses pre-baked CRACKS texture instead of procedural drawing
    drawGroundCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'lighter'; 
        ctx.globalAlpha = intensity;

        // Slight rotation for variety based on position (pseudo-random)
        // using x coordinate as seed to keep it static per tile
        const staticRot = (x % 3) * (Math.PI / 3);
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -half, -half, size, size);

        ctx.restore();
    },

    // Original Extruded Hex (Kept for basic fields/walls/indicators)
    drawExtrudedHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number,
        isHollow: boolean = false
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity * 0.6;

        for (const i of VISIBLE_FACES) {
            const idx1 = i;
            const idx2 = (i + 1) % 6;

            const c1 = HEX_CORNERS[idx1];
            const c2 = HEX_CORNERS[idx2];

            let shade = 1.0;
            if (i === 5) shade = 0.7; 
            if (i === 0) shade = 0.5; 
            if (i === 1) shade = 0.9; 

            // NOTE: Gradient here is still needed for depth, but it's only 3 per hex
            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c2.x, topY + c2.y);
            ctx.lineTo(x + c2.x, bottomY + c2.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.closePath();

            const oldAlpha = ctx.globalAlpha;
            ctx.globalAlpha = oldAlpha * shade;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.8;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.stroke();

            ctx.globalAlpha = oldAlpha;
        }

        if (!isHollow) {
            ctx.globalAlpha = opacity;
            ctx.fillStyle = color;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = opacity * 0.5;
            this.pathHex(ctx, x, topY, 0.8);
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        this.pathHex(ctx, x, topY, 1.0);
        ctx.stroke();

        ctx.restore();
    },

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        // Optimized Seed: Use bitwise ops for speed
        const seed = ((q * 73856093) ^ (r * 19349663)) / 2147483647; 
        const normalizedSeed = Math.abs(seed - Math.floor(seed));

        if (type === 'MAGMA') {
            if (normalizedSeed > 0.5) {
                // Using the optimized drawGroundCracks which now uses cache
                this.drawGroundCracks(ctx, cx, cy, '#ef4444', 0.6);
            }
        } else if (type === 'VOID') {
            // VOID texture logic remains simple rects, but use context save/restore carefully
            if (normalizedSeed > 0.7) {
                ctx.save();
                ctx.fillStyle = '#38bdf8';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(cx - 2, cy - 2, 4, 4);

                ctx.strokeStyle = color;
                ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+10, cy-5); ctx.stroke();
                ctx.restore();
            }
        }
    },

    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        const r = HEX_SIZE * 0.8 * progress; 
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();
        ctx.rotate(t * 2);
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI/4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, Math.PI + Math.PI/4); ctx.stroke();
        ctx.restore();
    }
};

payload.text:
你好！作為你的高階系統工程師，我已深入檢視了目前的程式碼庫。目前的架構已經相當成熟，特別是在邏輯分層上（`engine/systems` vs `components`），但確實到了需要將「資源（Assets）」與「程式邏輯（Logic）」進一步解耦的階段，以便於未來的擴充和維護。

以下是針對你提出的四點評估與架構重構建議：

### 1. 評估技能系統 (Skill System) 目前拆解狀態

**現狀評估：**
*   **優點：** 資料結構化程度很高。`Skill` 介面定義清晰，且透過 `data/skills/*.ts` 進行了細粒度的檔案拆分（Blue/Red, Basic/Active/Ult），這非常優秀。這意味著新增技能只需新增資料，無需改動引擎核心。
*   **缺點：** 視覺綁定仍然依賴「字串列舉 (String Enum)」。例如 `visual: 'BOLT'` 或 `visual: 'SMASH'`。這導致 `ProjectileRenderer.ts` 和 `EventVFXMapper.ts` 中充滿了大量的 `switch/if` 判斷式來決定具體要畫什麼。
*   **瓶頸：** 當你想為某個特定技能（例如「諸神黃昏」）製作獨一無二的特效時，你目前必須在 `EventVFXMapper` 寫一段專屬的程式碼（如 `spawnCovenantRagnarok`），這破壞了「技能只是資料」的原則，變成了「技能資料 + 硬編碼的特效邏輯」。

### 2. 評估特效系統 (VFX System) 目前拆解狀態

**現狀評估：**
*   **優點：** 粒子系統（`ParticleRenderer` + `VFXSystem`）效能良好，支援多種繪製模式（圖片、Canvas路徑、預烘焙貼圖）。`VFXFactory` 的引入極大優化了效能（快取 Canvas）。
*   **缺點：** 特效生成邏輯是「指令式 (Imperative)」而非「宣告式 (Declarative)」。
    *   目前的 `engine/systems/vfx/spawners/*.ts`（如 `imperial.ts`）全部是 TypeScript 函數。
    *   例如 `spawnImperialSanctuary` 函數內部手寫了「生成一個光柱、然後迴圈生成6個光束」。
*   **風險：** 這意味著美術設計師無法調整特效（如改顏色、改數量、改速度），必須由工程師修改程式碼。這不符合「資產化」的標準。

### 3. 評估網格系統 (Grid System) 目前拆解狀態

**現狀評估：**
*   **優點：** `GridSystem` 與 `TerrainRenderer` 運作良好，能夠處理高度與遮擋。
*   **缺點：** 地形特效與技能特效是割裂的。
    *   `ZoneRenderer.ts` 裡面的 `drawActiveHazard` 針對 'FIRE'、'POISON' 寫死了渲染邏輯（呼叫 `SurfaceAssets`）。
    *   這導致如果一個技能產生「毒霧」，和地圖本身的「毒沼地形」，可能用了兩套不同的渲染路徑，或者難以共用同一個「毒霧粒子設定」。

---

### 4. 評估與架構方案：特效資源資產化 (VFX Assetization)

你構想的 **「每一種特效都有一個自身的描述模型檔」** 是正確的演進方向。這就是現代遊戲引擎（如 Unity 的 Prefab 或 UE 的 Niagara）的做法。

#### 核心架構提案：VFX Manifest System

我們需要從 **「寫程式碼產生粒子」** 轉變為 **「讀取設定檔產生粒子」**。

**步驟 (i): 定義特效資產模型 (The VFX Asset Schema)**

不要再寫 `spawnExplosion()` 函數，而是定義一個 JSON 結構（TypeScript Interface）來描述特效。

```typescript
// types/VFXSchema.ts (新檔案)

export type EmitterShape = 'POINT' | 'CIRCLE' | 'CONE' | 'LINE' | 'HEX_GRID';

// 單個粒子發射器的設定
export interface ParticleEmitterConfig {
    particleType: 'SMOKE' | 'SPARK' | 'GLOW' | 'SHARD' | 'TEXTURE';
    textureId?: string; // 如果是 TEXTURE 類型，對應 VFXFactory 的 key
    blendMode: 'source-over' | 'lighter' | 'screen';

    count: number;          // 一次發射多少顆
    rate: number;           // 每秒發射多少顆 (0 為單次爆發)
    duration: number;       // 發射器持續時間
    delay: number;          // 延遲啟動

    // 物理參數 (使用範圍 [min, max] 來製造隨機性)
    life: [number, number];
    speed: [number, number];
    size: [number, number];
    rotationSpeed: [number, number];
    gravity: number;
    drag: number;

    // 顏色漸變 (Start -> End)
    colors: string[]; 

    // 空間分佈
    shape: EmitterShape;
    shapeRadius: number;
}

// 一個完整的特效資產 (可以包含多個發射器，例如：核心光暈 + 飛濺火花 + 煙霧拖尾)
export interface VFXAsset {
    id: string;           // e.g., "FX_FIREBALL_HIT"
    emitters: ParticleEmitterConfig[];
    soundRef?: string;    // 未來可擴充音效
}
```

**步驟 (ii): 建立特效註冊表 (VFX Registry)**

建立一個中央資料庫（類似 `SkillDB`），存放所有的 `VFXAsset`。

```typescript
// data/vfx_assets/index.ts
import { VFXAsset } from '../../types/VFXSchema';

export const VFX_DB: Record<string, VFXAsset> = {
    'FX_IMPERIAL_HIT': {
        id: 'FX_IMPERIAL_HIT',
        emitters: [
            {
                particleType: 'BLAST',
                count: 1,
                life: [0.2, 0.2],
                size: [60, 80],
                colors: ['#ffffdd'],
                blendMode: 'screen',
                shape: 'POINT',
                // ... 其他參數
            },
            {
                particleType: 'SPARK',
                count: 10,
                life: [0.3, 0.5],
                speed: [300, 600],
                colors: ['#3b82f6'],
                blendMode: 'lighter',
                shape: 'CIRCLE',
                shapeRadius: 10
                // ... 其他參數
            }
        ]
    }
    // ... 定義數百個特效
};
```

**步驟 (iii): 重構 VFXSystem (The Generic Spawner)**

`VFXSystem` 不再需要知道什麼是 "Imperial Sanctuary"，它只需要知道如何「播放一個 VFXAsset」。

```typescript
// engine/systems/vfx/VFXSystem.ts (修改)

public playEffect(effectId: string, position: {x: number, y: number, z: number}, configOverride?: any) {
    const asset = VFX_DB[effectId];
    if (!asset) return;

    for (const emitterConfig of asset.emitters) {
        // 這裡編寫通用的邏輯：
        // 根據 emitterConfig 的數據，計算隨機數，
        // 從 Object Pool 取出粒子，並賦值 (x, y, vx, vy, color...)
        this.spawnParticlesFromConfig(emitterConfig, position);
    }
}
```

**步驟 (iv): 技能與網格的引用 (Reference)**

1.  **技能系統：**
    修改 `Skill` 介面，將 `visual` 欄位指向 `VFXAsset` 的 ID。
    ```typescript
    // data/skills/blue_basic.ts
    { 
        id: 'tb_b1', 
        // 舊的: visual: 'SMASH', color: '#facc15'
        // 新的: 
        visualHitEffect: 'FX_HOLY_SMASH_HIT', 
        visualCastEffect: 'FX_HOLY_CAST',
        projectileEffect: 'FX_HOLY_BOLT_PROJ'
    }
    ```

2.  **網格系統 (Hazards)：**
    修改 `GroundHazard`，不再寫死 `type: 'FIRE'`，而是引用特效 ID。
    ```typescript
    // engine/systems/map.ts
    engine.map.addHazard({
        // ...
        vfxId: 'FX_ENVIRONMENT_LAVA_BUBBLES' // 引用同一個資源庫
    });
    ```

### 總結效益

透過這個改動：
1.  **技能** 變成了純粹的數值容器，它只說「我要播放 `FX_FIRE_HIT`」，不關心特效長什麼樣。
2.  **網格** 可以重複使用技能的特效資源（例如：技能造成的燃燒地面，和地圖自帶的岩漿，可以共用同一個 `FX_LAVA_LOOP` 設定檔）。
3.  **擴充性**：你甚至可以開發一個簡單的「特效編輯器 UI」，調整滑桿並即時預覽，匯出 JSON 供遊戲使用，而完全不需要動到 TypeScript 程式碼。

**下一步建議：**
如果您同意這個方向，我們可以先從建立 `VFXSchema` 和將一個簡單的特效（例如 `Generic Explosion`）轉化為 JSON 資料結構開始實作。

diffs.replacement:
// ==========================================
// 🎨 VFX ASSET SCHEMA (Data-Driven)
// ==========================================

export type ParticleType = 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'BLAST' | 'CHIP';
export type EmitterShape = 'POINT' | 'CIRCLE' | 'CONE' | 'BURST_DIR';
export type BlendMode = 'source-over' | 'lighter' | 'screen' | 'overlay';

// Range Helper [min, max] for randomness
export type Range = [number, number]; 

export interface EmitterConfig {
    // Identity
    id?: string;
    particleType: ParticleType;
    textureId?: string; // Optional: If specific texture needed from VFXFactory

    // Spawning Logic
    count: number | Range; // How many particles
    delay: number | Range; // Start delay
    lifetime: Range;       // How long particles live

    // Physics
    speed: Range;
    gravity?: number;      // Override default gravity
    drag?: number;         // Air resistance (0-1)

    // Visuals
    size: Range;
    colors: string[];      // Randomly picked from array
    blendMode?: BlendMode;

    // Transform
    shape: EmitterShape;
    shapeRadius?: number;  // For Circle/Cylinder

    // Advanced
    locked?: boolean;      // If true, moves with parent/source
    vRotation?: Range;     // Angular velocity
}

export interface VFXAsset {
    id: string;
    description?: string;
    emitters: EmitterConfig[];
    soundRef?: string;
}

import { VFXAsset } from "../../types/VFXSchema";

// ==========================================
// 📚 VFX ASSET DATABASE
// This file replaces hardcoded spawner functions.
// ==========================================

export const VFX_REGISTRY: Record<string, VFXAsset> = {

    // 範例：通用打擊特效 (替代原本的 Generic.addImpact 'BLAST')
    'FX_GENERIC_HIT': {
        id: 'FX_GENERIC_HIT',
        description: 'Standard impact flash and sparks',
        emitters: [
            // 1. Central Flash
            {
                particleType: 'BLAST',
                count: 1,
                life: [0.2, 0.2],
                size: [50, 70],
                speed: [0, 0],
                colors: ['#ffffdd'],
                shape: 'POINT',
                delay: 0,
                blendMode: 'screen'
            },
            // 2. Glow Halo
            {
                particleType: 'GLOW',
                count: 1,
                life: [0.3, 0.3],
                size: [80, 100],
                speed: [0, 0],
                colors: ['#ffffff'], // Will be overridden by dynamic color usually
                shape: 'POINT',
                delay: 0,
                blendMode: 'screen'
            },
            // 3. Flying Sparks
            {
                particleType: 'SPARK',
                count: [6, 10],
                life: [0.3, 0.5],
                size: [3, 6],
                speed: [300, 600], // Fast explosion
                gravity: 500,
                colors: ['#ffffff', '#ffff00'],
                shape: 'BURST_DIR', // Omnidirectional burst
                delay: 0,
                blendMode: 'lighter'
            }
        ]
    }
};

import { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";

// Helper: Get random number from Range [min, max] or number
const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};

// Helper: Pick random color
const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};

export class VFXPlayer {

    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string) {
        const asset = VFX_REGISTRY[effectId];

        if (!asset) {
            console.warn(`VFXPlayer: Asset '${effectId}' not found.`);
            return;
        }

        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride);
        }
    }

    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string) {
        const count = Math.floor(rnd(config.count));

        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();

            // 1. Position & Velocity Calculation based on Shape
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = cz;
            const speed = rnd(config.speed);

            if (config.shape === 'POINT') {
                // No offset
            } 
            else if (config.shape === 'BURST_DIR') {
                // Omnidirectional Sphere Burst
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);

                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); // Bias upwards slightly
            }
            else if (config.shape === 'CIRCLE') {
                // Flat ring burst
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;

                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }

            // 2. Properties
            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;

            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);

            p.size = rnd(config.size);

            // Color priority: Override > Config
            p.color = colorOverride || pickColor(config.colors);

            // Type Casting (Ensure string matches Particle internal type)
            p.type = config.particleType as any;

            // Optional Physics Overrides
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.vRotation) p.vRotation = rnd(config.vRotation);
            else p.vRotation = (Math.random() - 0.5) * 10; // Default gentle rotation

            // Push to System
            system.state.particles.push(p);
        }
    }
}

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";

const GRAVITY = 1800; 

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambientTimer: number = 0;

    public reset() {
        this.state.reset();
        this.ambientTimer = 0;
    }

    /**
     * New Data-Driven Entry Point (Phase 1)
     * @param effectId ID key from VFXRegistry
     * @param x World X
     * @param y World Y
     * @param z Height Z (Terrain + Unit)
     * @param colorOverride Optional: Force a specific color (e.g. Team Color)
     */
    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride);
    }

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // --- V2.0 PHYSICS LOCK ---
            // Locked particles are purely visual/kinematic (controlled by spawner or static)
            if (p.locked) {
                p.rotation += p.vRotation * dt;
                continue; 
            }

            // --- KILL AT TARGET ---
            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX;
                const dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) {
                    p.life = 0; 
                }
            }

            // --- PHYSICS UPDATE ---
            const isPhysical = p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'SPRITE' || p.type === 'ROCK';

            if (isPhysical) {
                let groundH = getTerrainHeight ? getTerrainHeight(p.x, p.y) : 0;

                // Apply Gravity to Z (Height)
                p.vz -= GRAVITY * dt;

                // Integrate
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                // Floor Collision
                if (p.z < groundH) {
                    p.z = groundH;
                    if (Math.abs(p.vz) > 100) {
                        p.vz = -p.vz * 0.5; // Bounce
                        p.vx *= 0.6; 
                        p.vy *= 0.6;
                        p.vRotation *= 0.5;
                    } else {
                        // Resting
                        p.vz = 0;
                        p.vx *= 0.1; 
                        p.vy *= 0.1;
                        p.vRotation = 0;
                        p.z = groundH; // Snap
                    }
                }
            } else {
                // Weightless / Atmospheric
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                if (p.drag !== undefined) {
                    const dragFactor = 1 - p.drag; 
                    p.vx *= dragFactor;
                    p.vy *= dragFactor;
                    p.vz *= dragFactor;
                } else if (p.type === 'SPARK' || p.type === 'SMOKE') {
                    p.vx *= 0.90; 
                    p.vy *= 0.90;
                    p.vz *= 0.90; 
                } else if (p.type === 'GLOW') {
                    // Float
                    p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                    p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
                }
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                this.state.decals.splice(i, 1);
            }
        }

        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;
        this.ambientTimer += dt;
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            const x = Math.random() * 1200 - 100;
            const y = Math.random() * 800 - 100;

            const p = this.state.getParticle();
            p.x = x; p.y = y; p.z = Math.random() * 200 + 50;
            p.type = 'GLOW';

            if (type === 'SNOW') {
                p.color = '#fff';
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 50 + Math.random() * 30;
                p.life = 3.0; p.maxLife = 3.0;
            } else if (type === 'ASH') {
                p.color = '#78350f';
                p.size = Math.random() * 4 + 1;
                p.vx = 30 + Math.random() * 30;
                p.vy = 20 + Math.random() * 20;
                p.life = 4.0; p.maxLife = 4.0;
            } else if (type === 'EMBER') {
                p.color = '#fbbf24';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 20;
                p.vy = -30 - Math.random() * 20;
                p.life = 2.0; p.maxLife = 2.0;
            } else if (type === 'SPORES') {
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 10;
                p.vy = (Math.random() - 0.5) * 10;
                p.life = 5.0; p.maxLife = 5.0;
            }
            this.state.particles.push(p);
        }
    }
}

