// ==========================================
// 🎨 VFX ASSET SCHEMA (Data-Driven)
// ==========================================

export type ParticleType = 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'BLAST' | 'CHIP' | 'PILLAR' | 'HEX_GLOW' | 'GRID_FIELD' | 'DOMAIN' | 'SPRITE' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX';
export type EmitterShape = 'POINT' | 'CIRCLE' | 'CONE' | 'BURST_DIR';
export type BlendMode = 'source-over' | 'lighter' | 'screen' | 'overlay';

// Range Helper [min, max] for randomness
export type Range = [number, number]; 

export interface EmitterConfig {
    // Identity
    id?: string;
    particleType: ParticleType;
    textureId?: string; // Optional: If specific texture needed from VFXFactory

    // Spawning Logic
    count: number | Range; // How many particles
    delay: number | Range; // Start delay
    lifetime: Range;       // How long particles live

    // Physics
    speed: Range;
    gravity?: number;      // Override default gravity
    drag?: number;         // Air resistance (0-1)

    // Visuals
    size: Range;
    colors: string[];      // Randomly picked from array
    blendMode?: BlendMode;

    // Transform
    shape: EmitterShape;
    shapeRadius?: number;  // For Circle/Cylinder

    // Advanced
    locked?: boolean;      // If true, moves with parent/source
    vRotation?: Range;     // Angular velocity
}

export interface VFXAsset {
    id: string;
    description?: string;
    emitters: EmitterConfig[];
    soundRef?: string;
}

import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { ULT_VISUALS, UltVisualDef } from "../../../data/ult_visuals";
import { UNIT_BODY_OFFSET } from "../../../constants";

// Import generic spawners to compose archetypes
import * as Generic from "../vfx/spawners/generic";

interface Point3D { x: number; y: number; z: number; }

export class UltArchitect {

    public static play(
        id: string, 
        target: Point3D, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem,
        sourceId?: string
    ): boolean {
        const def = ULT_VISUALS[id];
        if (!def) return false; // Not defined in data, fall back to legacy/generic

        const { archetype, primaryColor, secondaryColor, scale, count, height, vfxOverride } = def;

        // Camera Trauma Scaling based on Impact Scale
        camera.addTrauma(0.3 * scale);

        switch (archetype) {
            case 'HEAVEN_FALL':
                this.playHeavenFall(vfx, target, primaryColor, secondaryColor, height || 1000, scale, vfxOverride);
                break;

            case 'SANCTUARY':
                this.playSanctuary(vfx, target, primaryColor, secondaryColor, count || 6, scale);
                break;

            case 'DOMAIN':
                this.playDomain(vfx, target, primaryColor, secondaryColor, scale, vfxOverride);
                break;

            case 'BEAM_SNIPE':
                this.playBeamSnipe(vfx, engine, grid, target, sourceId, primaryColor, secondaryColor, scale);
                break;

            case 'STORM':
                this.playStorm(vfx, target, primaryColor, secondaryColor, count || 10, scale, vfxOverride);
                break;

            case 'INSTANT_IMPACT':
                this.playInstantImpact(vfx, target, primaryColor, secondaryColor, scale, vfxOverride);
                break;
        }

        return true;
    }

    private static playHeavenFall(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, height: number, scale: number, type?: string) {
        // 1. The Falling Object
        const projectile = vfx.state.getParticle();
        projectile.x = target.x; 
        projectile.y = target.y; 
        projectile.z = target.z + height;

        projectile.vx = 0; 
        projectile.vy = 0; 

        // Calculate speed to hit roughly in 0.4s
        const speed = height / 0.4;
        projectile.vz = -speed;

        projectile.life = 0.45; // slightly longer to ensure hit
        projectile.maxLife = 0.45;
        projectile.color = pColor;
        projectile.size = 100 * scale;
        projectile.type = (type as any) || 'GIANT_HEX'; // Default to Hex if not specified

        if (projectile.type === 'GIANT_HEX') projectile.rotation = Math.random() * Math.PI;

        vfx.state.particles.push(projectile);

        // 2. The Impact (Delayed)
        setTimeout(() => {
            Generic.spawnExplosion(vfx, target.x, target.y, target.z, 20, sColor, 3.0 * scale, 1.0, 'DEBRIS');
            Generic.spawnShockwave(vfx, target.x, target.y, target.z, pColor, 1.2);
            Generic.addImpact(vfx, target.x, target.y, target.z, sColor, 'BLAST', 0.8 * scale);
        }, 400);
    }

    private static playSanctuary(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, count: number, scale: number) {
        // Center Pillar
        const beacon = vfx.state.getParticle();
        beacon.x = target.x; beacon.y = target.y; beacon.z = target.z;
        beacon.life = 3.0; beacon.maxLife = 3.0;
        beacon.color = pColor; 
        beacon.size = 40 * scale; 
        beacon.type = 'PILLAR'; 
        beacon.locked = true; 
        vfx.state.particles.push(beacon);

        // Surrounding Beams
        const radius = 160 * scale;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const px = target.x + Math.cos(angle) * radius;
            const py = target.y + Math.sin(angle) * radius;
            const start = { x: px, y: py, z: target.z + 10 };
            const end = { x: target.x, y: target.y, z: target.z + 40 };
            Generic.spawnBeam(vfx, start, end, sColor, 3.0, 2 * scale);
        }
    }

    private static playDomain(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, scale: number, overrideType?: string) {
        // Base Zone
        const zone = vfx.state.getParticle();
        zone.x = target.x; zone.y = target.y; zone.z = target.z;
        zone.life = 4.0; zone.maxLife = 4.0;
        zone.color = pColor; 
        zone.size = 250 * scale;
        zone.type = (overrideType as any) || 'DOMAIN'; 
        zone.locked = true;
        vfx.state.particles.push(zone);

        // Initial Shockwave
        Generic.spawnShockwave(vfx, target.x, target.y, target.z, sColor, 1.5);
    }

    private static playBeamSnipe(vfx: VFXSystem, engine: GameEngine, grid: GridSystem, target: Point3D, sourceId: string | undefined, pColor: string, sColor: string, scale: number) {
        if (!sourceId) return;
        const srcAgent = engine.agents.find(a => a.id === sourceId);
        if (!srcAgent) return;

        // Resolve Source Point including body height
        const terrainH = grid.getTerrainHeight(srcAgent.q, srcAgent.r, engine);
        const srcPt = {
            x: srcAgent.px,
            y: srcAgent.py,
            z: terrainH + srcAgent.physics.z + UNIT_BODY_OFFSET
        };

        // Beam
        if (pColor === '#000') {
             // Railgun style (Black core, colored glow)
             Generic.spawnDeathRay(vfx, srcPt, target, '#000');
             Generic.spawnShockwave(vfx, srcPt.x, srcPt.y, srcPt.z, sColor, 0.5);
        } else {
             Generic.spawnDeathRay(vfx, srcPt, target, pColor);
        }

        // Impact at target
        Generic.addImpact(vfx, target.x, target.y, target.z, sColor, 'BLAST', 0.5 * scale);
    }

    private static playStorm(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, count: number, scale: number, overrideType?: string) {
        const radius = 200 * scale;

        for(let i=0; i<count; i++) {
            const p = vfx.state.getParticle();
            const a = Math.random() * Math.PI * 2;
            const r = Math.random() * radius;

            p.x = target.x + Math.cos(a) * r;
            p.y = target.y + Math.sin(a) * r;

            const isRain = overrideType === 'BEAM';

            if (isRain) {
                p.z = target.z + 500;
                p.vx = 0; p.vy = 0; p.vz = -800;
                p.life = 0.6; p.maxLife = 0.6;
                p.type = 'BEAM'; // Rain drop reuse
                p.size = 3;
            } else {
                // Chaotic movement (Bladestorm / Firestorm)
                p.z = target.z + Math.random() * 50;
                p.vx = (Math.random()-0.5) * 200;
                p.vy = (Math.random()-0.5) * 200;
                p.vz = 50 + Math.random() * 100;
                p.life = 1.5; p.maxLife = 1.5;
                p.type = (overrideType as any) || 'SMOKE';
                p.size = 15 * scale;
            }

            p.color = Math.random() > 0.5 ? pColor : sColor;
            p.delay = i * 0.05;

            vfx.state.particles.push(p);
        }
    }

    private static playInstantImpact(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, scale: number, overrideType?: string) {
        if (overrideType === 'GRID_FIELD') {
            const grid = vfx.state.getParticle();
            grid.x = target.x; grid.y = target.y; grid.z = target.z;
            grid.life = 2.0; grid.maxLife = 2.0;
            grid.color = pColor; grid.size = 200 * scale;
            grid.type = 'GRID_FIELD'; grid.locked = true;
            vfx.state.particles.push(grid);
        } else {
            Generic.spawnExplosion(vfx, target.x, target.y, target.z, 15, pColor, 4.0 * scale, 1.0, (overrideType as any) || 'SPARK');
        }

        Generic.addImpact(vfx, target.x, target.y, target.z, sColor, 'BLAST', 0.8 * scale);
        Generic.spawnShockwave(vfx, target.x, target.y, target.z, pColor, 1.0 * scale);
    }
}

import { GameEvent, Team } from "../../../types";
import { GameEngine, Agent } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET, THEME_IMPERIAL, THEME_COVENANT } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import { UltArchitect } from "./UltArchitect";

// Explicit 3D Point Interface (Terrain Z + Physics Z + Body Offset)
interface Point3D { x: number; y: number; z: number; }

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        // 1. Calculate Absolute 3D Points (World X, World Y, Terrain Z + Body Height)
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine, grid);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine, grid);

        // Ground Z for surface effects (No body offset)
        const groundZ = grid.getTerrainHeight(
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).q,
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).r,
            engine
        );

        // Fallback: If hitting ground (no unit), lift target slightly to avoid z-fighting
        if (!event.targetId) target.z = groundZ + 20;

        switch (event.type) {
            // --- BEAMS & CONNECTORS ---
            case 'VISUAL_SLASH':
                if (event.sourceId && event.targetId) {
                    Generic.spawnConnectorSlash(vfx, origin, target, event.color || '#fff');
                }
                break;

            case 'VISUAL_BEAM':
                // Check if this beam is actually an Ult masquerading as a basic visual event
                if (event.skill && event.skill.tag === 'ULT') {
                     if (UltArchitect.play(event.skill.id, target, engine, vfx, grid, camera, event.sourceId)) {
                         return;
                     }
                }

                // Generic Beam
                Generic.spawnBeam(vfx, origin, target, event.color || '#fff');
                Generic.addImpact(vfx, target.x, target.y, target.z, event.color || '#fff', 'BLAST', 0.4);
                break;

            // --- IMPACTS ---
            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, target);
                }
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, vfx, grid, target, groundZ, camera); 
                } else {
                    Generic.addImpact(vfx, event.pos.x, event.pos.y, groundZ + 10, event.skill?.color || '#fff', 'BLAST', 0.3);
                }
                break;

            // --- AOE & SKILLS ---
            case 'IMPACT_AOE':
                this.handleAOE(event, engine, vfx, grid, camera, groundZ);
                break;

            // --- UNITS ---
            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    // Use origin which has body offset
                    Generic.spawnUnitShatter(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, origin.x, origin.y, origin.z, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, origin.x, origin.y, origin.z, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine, grid: GridSystem): Point3D {
        let agent = agentId ? engine.agents.find(a => a.id === agentId) : null;

        if (!agent && !agentId) {
            const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
            agent = engine.getAgentAt(hex.q, hex.r);
        }

        if (agent) {
            const terrainH = grid.getTerrainHeight(agent.q, agent.r, engine);
            return {
                x: agent.px,
                y: agent.py,
                z: terrainH + agent.physics.z + UNIT_BODY_OFFSET
            };
        }

        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = grid.getTerrainHeight(hex.q, hex.r, engine);

        return {
            x: defaultX,
            y: defaultY,
            z: terrainH 
        };
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, target: Point3D) {
        let dx = 0; let dy = -1;
        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const diffX = t.px - s.px; 
                const diffY = t.py - s.py;
                const len = Math.sqrt(diffX*diffX + diffY*diffY);
                if (len > 0) { dx = diffX/len; dy = diffY/len; }
                const isVictimBlue = t.team === Team.BLUE;
                const debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;
                Generic.spawnPhysicsSplatter(vfx, target.x, target.y, target.z, dx, dy, debrisColor);
                return;
            }
        }

        // Check: Does the skill have a specific Hit Effect?
        if (event.skill && event.skill.visualHitEffect) {
            vfx.playEffect(event.skill.visualHitEffect, target.x, target.y, target.z, event.color);
            return;
        }

        // Fallback: Generic Physics Splatter
        Generic.spawnPhysicsSplatter(vfx, target.x, target.y, target.z, 0, -1, event.color || '#94a3b8');
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, target: Point3D, groundZ: number, camera: CameraSystem): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        // 1. DATA-DRIVEN ARCHITECT (Replaces Hardcoded Switch)
        if (isUlt && skill) {
            // Try to find a definition in ult_visuals.ts
            if (UltArchitect.play(skill.id, target, engine, vfx, grid, camera, event.sourceId)) {
                return; 
            }
        }

        // 2. DATA-DRIVEN: VISUAL HIT EFFECT (Simple particles)
        if (skill && skill.visualHitEffect) {
            vfx.playEffect(skill.visualHitEffect, target.x, target.y, target.z, color);
            return;
        }

        // 3. FALLBACK
        camera.addTrauma(0.2); 

        if (faction === Team.BLUE) {
            Generic.addImpact(vfx, target.x, target.y, target.z, color, 'BLAST', 0.6);
            Generic.spawnShockwave(vfx, target.x, target.y, target.z, color, 0.4);
        } else {
            Generic.spawnBloodRitual(vfx, target.x, target.y, target.z, color, 1.2);
        }
    }

    private handleAOE(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, camera: CameraSystem, groundZ: number) {
        if (!event.skill) return;
        const centerPt = { x: event.pos.x, y: event.pos.y, z: groundZ };
        const color = event.color || '#fff';

        // 1. DATA-DRIVEN ARCHITECT
        if (UltArchitect.play(event.skill.id, centerPt, engine, vfx, grid, camera, event.sourceId)) {
            return;
        }

        // 2. DATA-DRIVEN: VISUAL HIT EFFECT (If defined for the skill itself)
        if (event.skill.visualHitEffect) {
            vfx.playEffect(event.skill.visualHitEffect, centerPt.x, centerPt.y, centerPt.z, color);
        }

        // 3. GRID SYSTEM REACTION (Data-Driven)
        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const radius = event.skill.aoeRadius || 1;
        const affectedHexes = HexUtils.range(centerHex, radius);
        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        // Determine which Grid Effect to play
        let gridEffectId = faction === Team.BLUE ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED';
        if (event.skill.ccType === 'PULL' || event.skill.visual === 'BOMB') {
             if (faction === Team.RED) gridEffectId = 'FX_GRID_IMPACT_RED';
        }
        if (event.skill.visual === 'BEAM') gridEffectId = 'FX_GRID_IMPACT_VOID';

        affectedHexes.forEach(h => {
            if (engine.map.isValid(h.q, h.r)) {
                const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                vfx.playEffect(gridEffectId, tilePos.x, tilePos.y, hHeight, color);
            }
        });

        // Generic Core Impact (Center)
        Generic.addImpact(vfx, event.pos.x, event.pos.y, groundZ, event.color || '#fff', 'BLAST', 0.5);
        camera.addTrauma(0.25); 
    }
}

