        p.vy = (Math.random()-0.5)*20; 
        p.vz = 10 + Math.random()*30; 
        p.life = duration * (0.6 + Math.random() * 0.4); p.maxLife = p.life;
        p.color = color; p.size = 25 + Math.random() * 25;
        p.type = type as any; 
        p.drag = 0.1; 
        p.delay = delay + Math.random() * 0.5;
        system.state.particles.push(p);
    }
}

