import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { getTransitionOffset } from "../utils";
import { Point } from "../../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../../data/projectile_visuals";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             // 1. Resolve Definition (ID > Visual Name > Default)
             const def: ProjectileVisualDef = PROJECTILE_VISUALS[p.skill.id] || PROJECTILE_VISUALS[p.skill.visual || 'BOLT'] || DEFAULT_PROJECTILE;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r) + (p.startZ || 0);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             const getVisualPos = (lx: number, ly: number, flightProgress: number): { x: number, y: number, shadowY: number } => {
                 const t = flightProgress;
                 const trajectoryTerrainHeight = hStart + (hEnd - hStart) * t;
                 const currentHex = HexUtils.fromPx(lx, ly, engine.mapConfig);
                 const groundHeight = getTerrainHeight(currentHex.q, currentHex.r);

                 // --- TRAJECTORY LOGIC ---
                 let arcOffset = 0;
                 let lateralOffset = 0;

                 if (def.trajectory === 'ARC') {
                     const distFactor = Math.min(150, totalDist * 0.25);
                     const baseArc = def.arcHeight || 50;
                     const arcHeight = baseArc + distFactor;
                     arcOffset = 4 * arcHeight * t * (1 - t);
                 } 
                 else if (def.trajectory === 'WOBBLE') {
                     const freq = def.wobbleFreq || 0.2;
                     const amp = def.wobbleAmp || 10;
                     lateralOffset = Math.sin(lx * freq + ly * freq) * amp;
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - trajectoryTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset - lateralOffset + off,
                     shadowY: ly - groundHeight + off
                 };
             };

             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // Look Ahead for Rotation
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));
             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = def.spinSpeed ? (progress * def.spinSpeed) : 0;

             // Trail Generation
             const visualTrail: Point[] = [];
             if ((def.trailLength || 0) > 0 && p.trail.length > 1) {
                 visualTrail.push({ x: headVis.x, y: headVis.y });
                 // Limit trail points based on config
                 const pointsToProcess = Math.min(p.trail.length, (def.trailLength || 5) + 1);

                 for (let i = p.trail.length - 1; i >= p.trail.length - pointsToProcess; i--) {
                     if (i < 0) break;
                     const tp = p.trail[i];
                     const tDist = Vector.dist({x: p.startX, y: p.startY}, tp);
                     const tProg = Math.min(1, Math.max(0, tDist / totalDist));
                     const tv = getVisualPos(tp.x, tp.y, tProg);
                     visualTrail.push({ x: tv.x, y: tv.y });
                 }
             }

             const op = renderList.next();
             op.type = RenderOpType.PROJECTILE;
             op.y = p.y + 50 + offsetP; 
             op.z = 20;

             op.proj = p;
             op.pVisX = headVis.x;
             op.pVisY = headVis.y;
             op.pVisShadowY = headVis.shadowY;
             op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
             op.pColor = def.colorOverride || p.skill.color;
             op.pIsUlt = p.skill.tag === 'ULT';
             op.pAngle = angle;
             op.pSpin = spin;
             op.pTrail = visualTrail; 

             // Pass Render Type info via existing fields (or repurpose)
             // We'll reuse pSkillVis for 'BEAM' logic inside GameRenderer if renderType is RAY/BEAM
             if (def.renderType === 'RAY' || def.renderType === 'BEAM') {
                 op.pSkillVis = 'BEAM'; // Triggers beam drawer in renderer
             }
        });
    }
};

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillResolutionSystem } from "./SkillResolutionSystem";
import { PROJECTILE_VISUALS } from "../../../data/projectile_visuals";

export class ProjectileSystem {
    public projectiles: Projectile[] = [];

    public update(dt: number, engine: GameEngine, skillResolver: SkillResolutionSystem) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            // 1. Resolve Definition
            const def = PROJECTILE_VISUALS[p.skill.id] || PROJECTILE_VISUALS[p.skill.visual || 'BOLT'];
            const isInstant = def ? def.trajectory === 'INSTANT' : false;

            // LOGICAL RAY DETECTION
            // High velocity skills or INSTANT trajectory move instantly
            const moveInstantly = isInstant || p.skill.projectileSpeed > 1400;

            const isGroundTarget = p.targetId.startsWith('ground-');
            let target = isGroundTarget ? null : engine.agents.find(a => a.id === p.targetId);

            if (target && !isGroundTarget) {
                p.targetPos = {x: target.px, y: target.py};
            }

            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const moveDist = moveInstantly ? 4000 * dt : p.speed * dt;

            // Update trail before moving
            const lastTrail = p.trail.length > 0 ? p.trail[p.trail.length - 1] : null;
            if (!lastTrail || Vector.dist(lastTrail, {x: p.x, y: p.y}) > 10) {
                p.trail.push({x: p.x, y: p.y});
                if (p.trail.length > 12) p.trail.shift(); 
            }

            // Reach target?
            if (dist <= moveDist || dist < 10) {
                const source = engine.agents.find(a => a.id === p.sourceId);

                if (p.skill.type === 'AOE') {
                    const hitPos = p.targetPos; 
                    const radius = p.skill.aoeRadius || 1;
                    const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                    const targets = engine.agents.filter(e => e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius);

                    targets.forEach(t => { 
                        if (source) skillResolver.resolveHit(source, t, p.skill, hitPos, engine); 
                    });

                    if (p.skill.ccType === 'DOT' || p.skill.name.includes("霧") || p.skill.name.includes("雨")) {
                        if (source) {
                            const centerHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                            const affectedTiles = HexUtils.range(centerHex, radius);
                            const dur = p.skill.ccDur || 5.0;
                            let hType: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC' = 'GENERIC';

                            if (p.skill.ccType === 'DOT') hType = 'POISON';
                            if (p.skill.name.includes('火') || p.skill.name.includes('Lava')) hType = 'FIRE';
                            if (p.skill.name.includes('冰') || p.skill.name.includes('Frost')) hType = 'ICE';

                            affectedTiles.forEach(tile => {
                                engine.map.addHazard(
                                    tile.q, tile.r, 
                                    hType, 
                                    dur, 
                                    source.id, 
                                    source.team, 
                                    p.skill.color,
                                    (p.skill.power * 0.2) || 10, 
                                    0.5 
                                );
                            });
                        }
                    }
                    engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
                } else {
                    if (target && target.hp > 0 && !target.banished) {
                        if (source) skillResolver.resolveHit(source, target, p.skill, undefined, engine);
                    }
                }
                engine.events.push({ type: 'PROJECTILE_HIT', pos: p.targetPos, skill: p.skill });

                this.removeProjectile(i);
            } else {
                const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    private removeProjectile(idx: number) {
        const lastIdx = this.projectiles.length - 1;
        if (idx !== lastIdx) this.projectiles[idx] = this.projectiles[lastIdx];
        this.projectiles.pop();
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        let targetPos = {x: 0, y: 0};
        let tid = "";

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 targetPos = p; tid = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 targetPos = {x: source.target.px, y: source.target.py}; tid = source.target.id;
             } else return;
             this.createProjectile(source, skill, targetPos, tid);
             engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: tid });
        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                targetPos = {x: source.target.px, y: source.target.py};
                this.createProjectile(source, skill, targetPos, source.target.id);
                engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: source.target.id });
            }
        }
    }

    private createProjectile(source: Agent, skill: Skill, targetPos: {x: number, y: number}, targetId: string) {
        this.projectiles.push({
            id: Math.random().toString(36).substr(2, 6),
            x: source.px, y: source.py, 
            startX: source.px, startY: source.py, startZ: source.physics.z, 
            targetId, targetPos,
            speed: skill.projectileSpeed || 600, skill, sourceId: source.id, team: source.team, trail: []
        });
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType, RenderOp } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public reset() {
        this.vfx.reset();
        this.hud.reset();
        this.camera.reset();
        this.eventListener.reset();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (Now utilizing strictly logical Y for stability)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            // PIXEL SNAPPING: Strictly align all translation anchors to integer coordinates
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlockGeometry(
                        ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, snapX, snapY - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time,
                        op.oHazard
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, snapX - OBSTACLE_HALF_WIDTH, snapY);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        // 1. Translate to the visual source position
                        ctx.translate(snapX, snapY);

                        const pProxy = op.particle;

                        // 2. Temporarily relativize coordinates for drawing in local space
                        const originalX = pProxy.x;
                        const originalY = pProxy.y;
                        const originalTx = pProxy.targetX;
                        const originalTy = pProxy.targetY;
                        // Don't need to restore targetZ as it's not mutated, but we read it.

                        // Visual Source becomes (0,0) in the new context
                        pProxy.x = 0; 
                        pProxy.y = 0;

                        // Fix for Beams: Convert absolute World Target to Relative Visual Target
                        if (pProxy.targetX !== undefined && pProxy.targetY !== undefined) {
                            // Target X relative to Source X (Horizontal distance)
                            pProxy.targetX = originalTx! - snapX; 

                            // VISUAL TARGET Y CALCULATION (Critical Fix)
                            // snapY = Source.y + Offset - Source.z
                            // We need TargetVisualY = Target.y + Offset - Target.z
                            // RelativeY = TargetVisualY - snapY

                            // Since we don't have the transition offset for the target here cheaply,
                            // we assume offset is similar (valid for beams which are short range).
                            // TargetVisualY ~= Target.y - Target.z ( + offset)

                            // relativeY = (originalTy - (pProxy.targetZ || 0)) - snapY.
                            // Note: originalTy from particle is Ground Y.

                            pProxy.targetY = (originalTy! - (pProxy.targetZ || 0)) - snapY; 
                        }

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        // 3. Restore original absolute coordinates
                        pProxy.x = originalX; 
                        pProxy.y = originalY;
                        pProxy.targetX = originalTx;
                        pProxy.targetY = originalTy;

                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything)
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') {
            transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        }

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) {
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            blurAmount = 1.0;
        }

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) {
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- VECTOR BEAM REFACTOR (Moving High-Speed Projectiles) ---
        // Data-driven check using the flag set by ProjectileRenderer from PROJECTILE_VISUALS
        const isRay = op.pSkillVis === 'BEAM'; 

        if (isRay && op.pTrail && op.pTrail.length > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';

            const start = op.pTrail[op.pTrail.length - 1]; 
            const end = { x: op.pVisX, y: op.pVisY };
            const dx = end.x - start.x;
            const dy = end.y - start.y;
            const len = Math.sqrt(dx*dx + dy*dy);
            const angle = Math.atan2(dy, dx);

            // 1. Energetic Core Beam
            const grad = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
            grad.addColorStop(0, 'rgba(0,0,0,0)');
            grad.addColorStop(0.2, op.pColor);
            grad.addColorStop(0.8, op.pColor);
            grad.addColorStop(1, '#fff');

            ctx.strokeStyle = grad;
            ctx.lineWidth = op.pIsUlt ? 6 : 3;
            ctx.lineCap = 'round';
            ctx.globalAlpha = 1.0;
            ctx.beginPath();
            ctx.moveTo(Math.round(start.x), Math.round(start.y));
            ctx.lineTo(Math.round(end.x), Math.round(end.y));
            ctx.stroke();

            // 2. Shock Rings (Mach Cones)
            if (len > 20) {
                const ringCount = Math.floor(len / 30);
                ctx.translate(start.x, start.y);
                ctx.rotate(angle);
                ctx.strokeStyle = op.pColor;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.6;

                for(let i=1; i<=ringCount; i++) {
                    const x = i * 30 - (this.globalTime * 200 % 30); 
                    if (x > 0 && x < len) {
                        ctx.beginPath();
                        ctx.ellipse(x, 0, 3, 10, 0, 0, Math.PI*2);
                        ctx.stroke();
                    }
                }
            }

            // 3. Bloom
            ctx.shadowColor = op.pColor;
            ctx.shadowBlur = 15;
            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = op.pIsUlt ? 16 : 8;
            ctx.globalAlpha = 0.3;
            ctx.stroke();
            ctx.shadowBlur = 0;

            ctx.restore();
            return;
        }

        // --- STANDARD SPRITE PROJECTILE ---
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath();
            const trail = op.pTrail;
            ctx.moveTo(Math.round(trail[0].x), Math.round(trail[0].y));
            for(let i=1; i<trail.length; i++) {
                ctx.lineTo(Math.round(trail[i].x), Math.round(trail[i].y));
            }
            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.stroke();
            ctx.restore();
        }

        const shadowAltitude = op.pVisShadowY - op.pVisY; 
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(Math.round(op.pVisX), Math.round(op.pVisShadowY));
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);
            ctx.scale(1, 0.5); 
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        ctx.save();
        ctx.translate(Math.round(op.pVisX), Math.round(op.pVisY));
        if (op.pSpin !== 0) ctx.rotate(op.pSpin); // Using calc spin from config
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

// =========================================================================================
// ⚡ BEAM VISUAL CONFIGURATION
// 
// Defines the look of continuous beams, lasers, and connectors.
// Used by ParticleRenderer to draw the beam between two points.
// =========================================================================================

export type BeamStyleType = 'STRAIGHT' | 'HELIX' | 'LIGHTNING' | 'VIBRANT';

export interface BeamVisualDef {
    type: BeamStyleType;
    width: number;          // Base width of the beam
    coreColor: string;      // Inner core color
    glowColor: string;      // Outer glow color

    // Animation
    noiseScale?: number;    // Jitter amount (0 = stable)
    helixFreq?: number;     // For HELIX: Frequency of sine wave
    helixAmp?: number;      // For HELIX: Amplitude of sine wave

    // Rendering
    blendMode?: GlobalCompositeOperation;
    texture?: string;       // Optional texture key
}

export const BEAM_VISUALS: Record<string, BeamVisualDef> = {
    // Standard Healer / Link Beam
    'GENERIC_BEAM': {
        type: 'HELIX',
        width: 6,
        coreColor: '#ffffff',
        glowColor: '#ffffff', // Will be overridden by skill color usually
        helixFreq: 0.1,
        helixAmp: 4,
        blendMode: 'screen'
    },

    // Ranger "Railgun" Ult / Mage "Death Finger"
    'DEATH_RAY': {
        type: 'STRAIGHT',
        width: 12,
        coreColor: '#000000', // Black Core
        glowColor: '#ef4444', // Red Glow (Default)
        noiseScale: 0,
        blendMode: 'normal'
    },

    // Quick slash connector (Melee hit line)
    'SLASH_CONNECT': {
        type: 'STRAIGHT',
        width: 16,
        coreColor: '#ffffff',
        glowColor: '#ffffff',
        noiseScale: 0,
        blendMode: 'overlay'
    },

    // Mage "Soul Drain"
    'DRAIN_LINK': {
        type: 'VIBRANT',
        width: 5,
        coreColor: '#d8b4fe',
        glowColor: '#a855f7',
        noiseScale: 2.0,
        blendMode: 'lighter'
    },

    // Teleport Pillar (Vertical Beam)
    'TELEPORT_PILLAR': {
        type: 'STRAIGHT',
        width: 40,
        coreColor: '#ffffff',
        glowColor: '#60a5fa',
        blendMode: 'screen'
    }
};

export interface Particle {
    active: boolean; 

    // Position (World Space - Ground Plane)
    x: number;
    y: number;
    z: number; // Current visual Z (height offset)

    // Physics
    vx: number;
    vy: number;
    vz: number;

    rotation: number;     
    vRotation: number;    

    life: number;
    maxLife: number;
    color: string;
    size: number;

    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP' | 'GRID_FIELD' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'HEX_GLOW';

    // 🎯 BEAM TARGETING (Explicit 3D Anchors)
    // We store Source and Target completely separately to emulate Projectile data structure
    sx?: number; sy?: number; sz?: number; // Start (World X, World Y, Terrain Z)
    tx?: number; ty?: number; tz?: number; // Target (World X, World Y, Terrain Z)

    // For moving particles
    targetX?: number; 
    targetY?: number; 
    targetZ?: number; 

    // Asset Keys
    beamStyle?: string; // New: Key for BEAM_VISUALS

    delay?: number;
    image?: HTMLCanvasElement; 

    // Flags
    locked?: boolean; 
    drag?: number;    
    killAtTarget?: number; 

    // Rendering
    texture?: HTMLCanvasElement; 
    blendMode?: GlobalCompositeOperation; 
    sortBias?: number; 
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            // Reset Properties
            p.active = true;
            p.x = 0; p.y = 0; p.z = 0;
            p.vx = 0; p.vy = 0; p.vz = 0;
            p.rotation = 0; p.vRotation = 0;
            p.life = 0; p.maxLife = 0;
            p.color = '#fff'; p.size = 0;
            p.type = 'SPARK';

            p.sx = undefined; p.sy = undefined; p.sz = undefined;
            p.tx = undefined; p.ty = undefined; p.tz = undefined;

            p.targetX = undefined;
            p.targetY = undefined;
            p.targetZ = undefined;

            p.image = undefined; 
            p.texture = undefined;
            p.blendMode = undefined;
            p.beamStyle = undefined; // Reset beam style

            p.delay = 0; 
            p.locked = false; 
            p.sortBias = 0; 
            p.drag = undefined; 
            p.killAtTarget = undefined; 

            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK',
            delay: 0,
            locked: false,
            sortBias: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        p.texture = undefined;
        this.particlePool.push(p);
    }

    public reset() {
        while (this.particles.length > 0) {
            const p = this.particles.pop();
            if (p) this.releaseParticle(p);
        }
        this.decals.length = 0;
    }
}

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";

const GRAVITY = 1800; 

// Interface for 3D points
interface Point3D { x: number; y: number; z: number; }

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambientTimer: number = 0;

    public reset() {
        this.state.reset();
        this.ambientTimer = 0;
    }

    /**
     * Play a particle effect from the registry
     */
    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride);
    }

    /**
     * Play a beam effect between two points
     */
    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();

        // 3D Anchors
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x;   p.ty = end.y;   p.tz = end.z;

        // Sorting Key (Start Point)
        p.x = start.x; p.y = start.y; p.z = start.z;

        p.life = duration; 
        p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; 
        p.beamStyle = styleId; // The crucial link to visual data
        p.locked = true;

        this.state.particles.push(p);
    }

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // --- V2.0 PHYSICS LOCK ---
            // Locked particles are purely visual/kinematic (controlled by spawner or static)
            if (p.locked) {
                p.rotation += p.vRotation * dt;
                continue; 
            }

            // --- KILL AT TARGET ---
            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX;
                const dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) {
                    p.life = 0; 
                }
            }

            // --- PHYSICS UPDATE ---
            const isPhysical = p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'SPRITE' || p.type === 'ROCK';

            if (isPhysical) {
                let groundH = getTerrainHeight ? getTerrainHeight(p.x, p.y) : 0;

                // Apply Gravity to Z (Height)
                p.vz -= GRAVITY * dt;

                // Integrate
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                // Floor Collision
                if (p.z < groundH) {
                    p.z = groundH;
                    if (Math.abs(p.vz) > 100) {
                        p.vz = -p.vz * 0.5; // Bounce
                        p.vx *= 0.6; 
                        p.vy *= 0.6;
                        p.vRotation *= 0.5;
                    } else {
                        // Resting
                        p.vz = 0;
                        p.vx *= 0.1; 
                        p.vy *= 0.1;
                        p.vRotation = 0;
                        p.z = groundH; // Snap
                    }
                }
            } else {
                // Weightless / Atmospheric
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                if (p.drag !== undefined) {
                    const dragFactor = 1 - p.drag; 
                    p.vx *= dragFactor;
                    p.vy *= dragFactor;
                    p.vz *= dragFactor;
                } else if (p.type === 'SPARK' || p.type === 'SMOKE') {
                    p.vx *= 0.90; 
                    p.vy *= 0.90;
                    p.vz *= 0.90; 
                } else if (p.type === 'GLOW') {
                    // Float
                    p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                    p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
                }
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                this.state.decals.splice(i, 1);
            }
        }

        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;
        this.ambientTimer += dt;
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            const x = Math.random() * 1200 - 100;
            const y = Math.random() * 800 - 100;

            const p = this.state.getParticle();
            p.x = x; p.y = y; p.z = Math.random() * 200 + 50;
            p.type = 'GLOW';

            if (type === 'SNOW') {
                p.color = '#fff';
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 50 + Math.random() * 30;
                p.life = 3.0; p.maxLife = 3.0;
            } else if (type === 'ASH') {
                p.color = '#78350f';
                p.size = Math.random() * 4 + 1;
                p.vx = 30 + Math.random() * 30;
                p.vy = 20 + Math.random() * 20;
                p.life = 4.0; p.maxLife = 4.0;
            } else if (type === 'EMBER') {
                p.color = '#fbbf24';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 20;
                p.vy = -30 - Math.random() * 20;
                p.life = 2.0; p.maxLife = 2.0;
            } else if (type === 'SPORES') {
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 10;
                p.vy = (Math.random() - 0.5) * 10;
                p.life = 5.0; p.maxLife = 5.0;
            }
            this.state.particles.push(p);
        }
    }
}

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { BEAM_VISUALS, BeamVisualDef } from "../../../../../data/vfx/beam_visuals";

const UNIT_CHEST_HEIGHT = 40;

// Optimization: Precomputed Unit Hexagon (Radius 1.0)
const HEX_CORNERS_X = [1, 0.5, -0.5, -1, -0.5, 0.5];
const HEX_CORNERS_Y = [0, 0.866, 0.866, 0, -0.866, -0.866];

function traceHexagonFast(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    ctx.moveTo(HEX_CORNERS_X[0] * r, HEX_CORNERS_Y[0] * r);
    for (let i = 1; i < 6; i++) {
        ctx.lineTo(HEX_CORNERS_X[i] * r, HEX_CORNERS_Y[i] * r);
    }
    ctx.closePath();
}

// Fallback if visual config missing
const DEFAULT_BEAM: BeamVisualDef = {
    type: 'HELIX',
    width: 6,
    coreColor: '#fff',
    glowColor: '#fff'
};

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. Base Position (Int Snapping for Speed)
        ctx.translate(Math.floor(p.x), Math.floor(p.y));

        const now = Date.now() / 1000;

        // 2. Texture Resolution
        if (!p.texture && !p.image && !['PILLAR', 'DOMAIN', 'HEX_BEAM', 'GIANT_HEX', 'GRID_FIELD', 'DEATH_RAY', 'BEAM'].includes(p.type)) {
            if (p.type === 'GLOW' || p.type === 'SPARK' || p.type === 'HEX_GLOW') p.texture = VFXFactory.getTexture('GLOW', p.color);
            else if (p.type === 'SMOKE') p.texture = VFXFactory.getTexture('NOISE', p.color);
            else if (p.type === 'BLAST') p.texture = VFXFactory.getTexture('BLAST', p.color);
            else if (p.type === 'DEBRIS' || p.type === 'ROCK') p.texture = VFXFactory.getTexture('SOLID', p.color);
            else if (p.type === 'HEX_LOCK' || p.type === 'SHOCKWAVE') p.texture = VFXFactory.getTexture('OUTLINE', p.color);

            // New Pre-baked types for performance
            else if (p.type === 'SHARD') p.texture = VFXFactory.getTexture('SHARD', p.color);
            else if (p.type === 'CHIP') p.texture = VFXFactory.getTexture('CHIP', p.color);
        }

        // 3. Render Logic
        if (p.image) {
            ctx.rotate(p.rotation);
            ctx.globalAlpha = 1 - progress;
            const size = Math.floor(p.size);
            ctx.drawImage(p.image, -size/2, -size/2, size, size);
        }
        else if (p.texture) {
            if (p.type === 'SMOKE' || p.type === 'GLOW' || p.type === 'HEX_GLOW') {
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = (1 - progress);
                const scale = p.type === 'SMOKE' ? (1 + progress) : (1 - progress * 0.5);
                ctx.scale(scale, scale);
                ctx.rotate(p.rotation);
                const s2 = p.size * 2;
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            } 
            else if (p.type === 'SPARK') {
                ctx.globalCompositeOperation = 'lighter';
                ctx.rotate(Math.atan2(p.vy, p.vx));
                ctx.scale(Math.min(3, 1 + p.size/10), 0.5);
                ctx.globalAlpha = 1 - progress;
                const s2 = p.size * 2;
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            }
            else {
                ctx.rotate(p.rotation);
                const s2 = p.size * 2;
                // Standard texture draw
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            }
        }
        else {
            this.drawProcedural(ctx, p, progress, isChaos, now);
        }

        ctx.restore();
    },

    drawProcedural(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean, now: number) {

        if (p.type === 'HEX_BEAM') {
            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1 - progress) * 0.9;
            traceHexagonFast(ctx, p.size); ctx.fill();
            ctx.fillStyle = '#fff';
            traceHexagonFast(ctx, p.size * 0.6); ctx.fill();
        }
        else if (p.type === 'GRID_FIELD') {
            if (p.color === '#be123c' || p.color.includes('blood')) {
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else {
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }
        }
        else if (p.type === 'PILLAR') {
            const h = 1200; 
            const width = p.size * (1 - progress * 0.5);

            ctx.save();
            ctx.globalCompositeOperation = 'screen';

            const grad = ctx.createLinearGradient(0, 0, 0, -h);
            grad.addColorStop(0, p.color);
            grad.addColorStop(0.2, '#fff');
            grad.addColorStop(1, 'rgba(0,0,0,0)');

            ctx.fillStyle = grad;
            ctx.globalAlpha = (1 - progress);
            ctx.fillRect(-width/2, -h, width, h);

            ctx.scale(1, ISO_SCALE_Y);
            ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2);
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.stroke();

            ctx.restore();
        }
        else if (p.type === 'DOMAIN') {
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 

            ctx.globalCompositeOperation = 'lighter';
            const grad = ctx.createRadialGradient(0, 0, r*0.5, 0, 0, r);
            grad.addColorStop(0, 'rgba(0,0,0,0)');
            grad.addColorStop(0.8, p.color);
            grad.addColorStop(1, 'rgba(255,255,255,0.5)');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.3 * (1 - progress);
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            ctx.strokeStyle = '#ffffff';
            ctx.globalAlpha = 0.15;
            ctx.lineWidth = 1;
            ctx.setLineDash([10, 10]);
            ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
        else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // New Beam Drawing Logic using Data
            if (p.sx !== undefined && p.sy !== undefined && p.sz !== undefined &&
                p.tx !== undefined && p.ty !== undefined && p.tz !== undefined) {

                const styleId = p.beamStyle || (p.type === 'DEATH_RAY' ? 'DEATH_RAY' : 'GENERIC_BEAM');
                const conf = BEAM_VISUALS[styleId] || DEFAULT_BEAM;

                const dx = p.tx - p.sx; 
                const startVisY = -UNIT_CHEST_HEIGHT;

                const worldYDelta = p.ty - p.sy;
                const zDelta = p.tz - p.sz;
                const targetVisY = worldYDelta - zDelta - UNIT_CHEST_HEIGHT;

                const dist = Math.sqrt(dx*dx + (targetVisY - startVisY)**2);
                const angle = Math.atan2(targetVisY - startVisY, dx);

                ctx.save();
                ctx.translate(0, startVisY); 
                ctx.rotate(angle);

                // Color Override Logic (Particle Color > Config Color)
                const coreCol = p.color !== '#fff' ? p.color : conf.coreColor;
                const glowCol = p.color !== '#fff' ? p.color : conf.glowColor;
                const width = conf.width * (p.size / 4); // Scale by particle size param

                if (conf.blendMode) ctx.globalCompositeOperation = conf.blendMode;

                if (conf.type === 'HELIX') {
                    const coreWidth = width * Math.sin((1-progress) * Math.PI);
                    if (coreWidth > 0.5) {
                        ctx.strokeStyle = glowCol;
                        ctx.globalAlpha = 0.3 * (1 - progress);
                        ctx.lineWidth = coreWidth * 6;
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                        ctx.globalCompositeOperation = 'lighter';
                        ctx.globalAlpha = 0.8 * (1 - progress);
                        ctx.lineWidth = Math.max(1, coreWidth * 0.8);

                        // Configurable Helix
                        const freq = conf.helixFreq || 0.1; 
                        const amp = (conf.helixAmp || 3) * (width / 4);
                        const speed = now * 20; 
                        const step = 10; 

                        ctx.beginPath();
                        for (let i = 0; i <= dist; i += step) {
                            const yOffset = Math.sin(i * freq - speed) * amp;
                            if (i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
                        }
                        ctx.stroke();

                        ctx.strokeStyle = coreCol;
                        ctx.lineWidth = Math.max(1, coreWidth);
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    }
                } 
                else if (conf.type === 'STRAIGHT' || conf.type === 'VIBRANT') {
                    const w = width * (1 - progress);
                    if (w > 0.5) {
                        // Outer Glow
                        ctx.strokeStyle = glowCol;
                        ctx.shadowColor = glowCol;
                        ctx.shadowBlur = (conf.noiseScale || 0) * 5 + 10;
                        ctx.lineWidth = w * 2;
                        ctx.globalAlpha = 0.6 * (1 - progress);

                        // Jitter for VIBRANT
                        let y1 = 0, y2 = 0;
                        if (conf.noiseScale && conf.noiseScale > 0) {
                            y1 = (Math.random()-0.5) * conf.noiseScale;
                            y2 = (Math.random()-0.5) * conf.noiseScale;
                        }

                        ctx.beginPath(); ctx.moveTo(0,y1); ctx.lineTo(dist, y2); ctx.stroke();
                        ctx.shadowBlur = 0;

                        // Inner Core
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.strokeStyle = coreCol;
                        ctx.lineWidth = w;
                        ctx.globalAlpha = 1.0;
                        ctx.beginPath(); ctx.moveTo(0,y1); ctx.lineTo(dist, y2); ctx.stroke();
                    }
                }

                ctx.restore();
            }
        }
        else if (p.type === 'GIANT_HEX') {
            ctx.scale(1, ISO_SCALE_Y);
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 0.8;
            traceHexagonFast(ctx, p.size); ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            traceHexagonFast(ctx, p.size); ctx.stroke();
        }
    }
};

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET, THEME_IMPERIAL, THEME_COVENANT } from "../../../constants";
import { SpriteManager } from "../../sprites";

// Architect
import { UltArchitect } from "./UltArchitect";

// Explicit 3D Point Interface
interface Point3D { x: number; y: number; z: number; }

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine, grid);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine, grid);

        const groundZ = grid.getTerrainHeight(
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).q,
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).r,
            engine
        );

        if (!event.targetId) target.z = groundZ + 20;

        switch (event.type) {
            case 'VISUAL_SLASH':
                if (event.sourceId && event.targetId) {
                    vfx.playBeam('SLASH_CONNECT', origin, target, event.color || '#fff', 0.2);
                }
                break;

            case 'VISUAL_BEAM':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (UltArchitect.play(event.skill.id, target, engine, vfx, grid, camera, event.sourceId)) {
                         return;
                     }
                }
                // Use generic beam logic
                vfx.playBeam('GENERIC_BEAM', origin, target, event.color || '#fff', 0.4);
                vfx.playEffect('FX_IMPACT_PHYSICAL', target.x, target.y, target.z, event.color);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, target);
                }
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, vfx, grid, target, groundZ, camera); 
                } else {
                    vfx.playEffect('FX_IMPACT_PHYSICAL', event.pos.x, event.pos.y, groundZ + 10, event.skill?.color);
                }
                break;

            case 'IMPACT_AOE':
                this.handleAOE(event, engine, vfx, grid, camera, groundZ);
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    // Spawn Manual Unit Parts (Can't be purely data-driven yet due to sprite generation)
                    this.spawnUnitShatter(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                vfx.playEffect('FX_TELEPORT', origin.x, origin.y, origin.z, event.color);
                break;

            case 'CAST_BREAK':
                vfx.playEffect('FX_CAST_BREAK', origin.x, origin.y, origin.z, event.color);
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine, grid: GridSystem): Point3D {
        let agent = agentId ? engine.agents.find(a => a.id === agentId) : null;

        if (!agent && !agentId) {
            const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
            agent = engine.getAgentAt(hex.q, hex.r);
        }

        if (agent) {
            const terrainH = grid.getTerrainHeight(agent.q, agent.r, engine);
            return {
                x: agent.px,
                y: agent.py,
                z: terrainH + agent.physics.z + UNIT_BODY_OFFSET
            };
        }

        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = grid.getTerrainHeight(hex.q, hex.r, engine);

        return {
            x: defaultX,
            y: defaultY,
            z: terrainH 
        };
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, target: Point3D) {
        if (event.skill && event.skill.visualHitEffect) {
            vfx.playEffect(event.skill.visualHitEffect, target.x, target.y, target.z, event.color);
            return;
        }
        // Fallback
        vfx.playEffect('FX_IMPACT_PHYSICAL', target.x, target.y, target.z, event.color || '#94a3b8');
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, target: Point3D, groundZ: number, camera: CameraSystem): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        if (isUlt && skill) {
            if (UltArchitect.play(skill.id, target, engine, vfx, grid, camera, event.sourceId)) {
                return; 
            }
        }

        if (skill && skill.visualHitEffect) {
            vfx.playEffect(skill.visualHitEffect, target.x, target.y, target.z, color);
            return;
        }

        camera.addTrauma(0.2); 
        if (faction === Team.BLUE) {
            vfx.playEffect('FX_IMPACT_PHYSICAL', target.x, target.y, target.z, color);
        } else {
            vfx.playEffect('FX_BLOOD_RITUAL', target.x, target.y, target.z, color);
        }
    }

    private handleAOE(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, camera: CameraSystem, groundZ: number) {
        if (!event.skill) return;
        const centerPt = { x: event.pos.x, y: event.pos.y, z: groundZ };
        const color = event.color || '#fff';

        if (UltArchitect.play(event.skill.id, centerPt, engine, vfx, grid, camera, event.sourceId)) {
            return;
        }

        if (event.skill.visualHitEffect) {
            vfx.playEffect(event.skill.visualHitEffect, centerPt.x, centerPt.y, centerPt.z, color);
        }

        // GRID SYSTEM REACTION
        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const radius = event.skill.aoeRadius || 1;
        const affectedHexes = HexUtils.range(centerHex, radius);
        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        let gridEffectId = faction === Team.BLUE ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED';
        if (event.skill.ccType === 'PULL' || event.skill.visual === 'BOMB') {
             if (faction === Team.RED) gridEffectId = 'FX_GRID_IMPACT_RED';
        }
        if (event.skill.visual === 'BEAM') gridEffectId = 'FX_GRID_IMPACT_VOID';

        affectedHexes.forEach(h => {
            if (engine.map.isValid(h.q, h.r)) {
                const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                vfx.playEffect(gridEffectId, tilePos.x, tilePos.y, hHeight, color);
            }
        });

        // Center Impact
        vfx.playEffect('FX_IMPACT_PHYSICAL', event.pos.x, event.pos.y, groundZ, event.color);
        camera.addTrauma(0.25); 
    }

    // Logic moved from generic.ts to keep specific sprite logic here
    private spawnUnitShatter(system: VFXSystem, x: number, y: number, z: number, team: Team, role: Role, impulseX: number = 0, impulseY: number = 0) {
        const assets = SpriteManager.getUnitImages(role, team);

        // 1. Core Components (Base & Icon) - Not data driven because they need specific Image Assets
        const base = system.state.getParticle();
