export interface EmitterConfig {
    // Identity
    id?: string;
    particleType: ParticleType;
    textureId?: string; // Optional: If specific texture needed from VFXFactory

    // Visual Style Reference (New)
    // Points to entries in BEAM_VISUALS or PROCEDURAL_VISUALS
    visualStyle?: string; 

    // Spawning Logic
    count: number | Range; // How many particles
    delay: number | Range; // Start delay
    lifetime: Range;       // How long particles live

    // Physics
    speed: Range;
    gravity?: number;      // Override default gravity
    drag?: number;         // Air resistance (0-1)

    // Visuals
    size: Range;
    colors: string[];      // Randomly picked from array
    blendMode?: BlendMode;

    // Transform
    shape: EmitterShape;
    shapeRadius?: number;  // For Circle/Cylinder

    // Advanced
    locked?: boolean;      // If true, moves with parent/source
    vRotation?: Range;     // Angular velocity
}

export interface VFXAsset {
    id: string;
    description?: string;
    emitters: EmitterConfig[];
    soundRef?: string;
}

export interface Particle {
    active: boolean; 

    // Position (World Space - Ground Plane)
    x: number;
    y: number;
    z: number; // Current visual Z (height offset)

    // Physics
    vx: number;
    vy: number;
    vz: number;

    rotation: number;     
    vRotation: number;    

    life: number;
    maxLife: number;
    color: string;
    size: number;

    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP' | 'GRID_FIELD' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'HEX_GLOW';

    // 🎯 BEAM TARGETING (Explicit 3D Anchors)
    // We store Source and Target completely separately to emulate Projectile data structure
    sx?: number; sy?: number; sz?: number; // Start (World X, World Y, Terrain Z)
    tx?: number; ty?: number; tz?: number; // Target (World X, World Y, Terrain Z)

    // For moving particles
    targetX?: number; 
    targetY?: number; 
    targetZ?: number; 

    // Asset Keys
    style?: string; // Generic Style Key (Looked up in BEAM_VISUALS or PROCEDURAL_VISUALS)

    delay?: number;
    image?: HTMLCanvasElement; 

    // Flags
    locked?: boolean; 
    drag?: number;    
    killAtTarget?: number; 

    // Rendering
    texture?: HTMLCanvasElement; 
    blendMode?: GlobalCompositeOperation; 
    sortBias?: number; 
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            // Reset Properties
            p.active = true;
            p.x = 0; p.y = 0; p.z = 0;
            p.vx = 0; p.vy = 0; p.vz = 0;
            p.rotation = 0; p.vRotation = 0;
            p.life = 0; p.maxLife = 0;
            p.color = '#fff'; p.size = 0;
            p.type = 'SPARK';

            p.sx = undefined; p.sy = undefined; p.sz = undefined;
            p.tx = undefined; p.ty = undefined; p.tz = undefined;

            p.targetX = undefined;
            p.targetY = undefined;
            p.targetZ = undefined;

            p.image = undefined; 
            p.texture = undefined;
            p.blendMode = undefined;
            p.style = undefined; // Reset style

            p.delay = 0; 
            p.locked = false; 
            p.sortBias = 0; 
            p.drag = undefined; 
            p.killAtTarget = undefined; 

            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK',
            delay: 0,
            locked: false,
            sortBias: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        p.texture = undefined;
        this.particlePool.push(p);
    }

    public reset() {
        while (this.particles.length > 0) {
            const p = this.particles.pop();
            if (p) this.releaseParticle(p);
        }
        this.decals.length = 0;
    }
}

// =========================================================================================
// 🔮 PROCEDURAL VISUAL CONFIGURATION
// 
// Defines the look of procedurally drawn particles (Pillars, Zones, Shapes).
// Replaces hardcoded rendering logic in ParticleRenderer.
// =========================================================================================

export type ProceduralType = 'PILLAR' | 'DOMAIN' | 'HEX_SHAPE' | 'IMPACT_RING';

export interface ProceduralVisualDef {
    type: ProceduralType;

    // Common
    blendMode?: GlobalCompositeOperation;

    // --- PILLAR SPECIFIC ---
    height?: number;        // Fixed height
    widthScale?: number;    // Width multiplier relative to particle size
    gradientTop?: string;   // 'transparent' or color
    gradientBottom?: string;// 'transparent' or color
    hasBaseRing?: boolean;  // Draw a ring at the base?

    // --- DOMAIN SPECIFIC ---
    rimColor?: string;      // Border color (defaults to particle color if null)
    fillAlpha?: number;     // Opacity of center fill
    rimWidth?: number;      // Stroke width
    dashed?: boolean;       // Dashed border?

    // --- HEX SHAPE SPECIFIC ---
    filled?: boolean;
    stroked?: boolean;
    strokeWidth?: number;
    innerScale?: number;    // For double hex (e.g. Hex Beam)
}

// Default Fallbacks
export const DEFAULT_PILLAR: ProceduralVisualDef = {
    type: 'PILLAR',
    height: 1200,
    widthScale: 1.0,
    gradientTop: 'transparent',
    gradientBottom: 'current', // Special keyword for particle.color
    hasBaseRing: true,
    blendMode: 'screen'
};

export const PROCEDURAL_VISUALS: Record<string, ProceduralVisualDef> = {
    // --- 1. PILLARS ---

    // Standard Teleport / Divine Pillar
    'PILLAR_HOLY': {
        type: 'PILLAR',
        height: 1200,
        widthScale: 1.0,
        gradientTop: 'transparent',
        gradientBottom: 'current',
        hasBaseRing: true,
        blendMode: 'screen'
    },

    // Dark Void Pillar (Opaque base)
    'PILLAR_VOID': {
        type: 'PILLAR',
        height: 1000,
        widthScale: 1.2,
        gradientTop: 'transparent',
        gradientBottom: '#000', // Black core
        hasBaseRing: false,
        blendMode: 'normal'
    },

    // --- 2. DOMAINS (Zones) ---

    // Standard Aura / Zone
    'DOMAIN_STANDARD': {
        type: 'DOMAIN',
        fillAlpha: 0.3,
        rimWidth: 1,
        dashed: true,
        blendMode: 'lighter'
    },

    // Heavy Shield Bubble
    'DOMAIN_SHIELD': {
        type: 'DOMAIN',
        fillAlpha: 0.1,
        rimWidth: 3,
        dashed: false,
        blendMode: 'screen'
    },

    // --- 3. HEX SHAPES ---

    // Giant Falling Hex (Heaven Fall)
    'HEX_SOLID': {
        type: 'HEX_SHAPE',
        filled: true,
        stroked: true,
        strokeWidth: 2,
        blendMode: 'source-over' // Opaque
    },

    // Hex Beam Core (Double Hex)
    'HEX_CORE': {
        type: 'HEX_SHAPE',
        filled: true,
        innerScale: 0.6, // Inner white core
        blendMode: 'lighter'
    }
};

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { BEAM_VISUALS, BeamVisualDef } from "../../../../../data/vfx/beam_visuals";
import { PROCEDURAL_VISUALS, DEFAULT_PILLAR, ProceduralVisualDef } from "../../../../../data/vfx/procedural_visuals";

const UNIT_CHEST_HEIGHT = 40;

// Optimization: Precomputed Unit Hexagon (Radius 1.0)
const HEX_CORNERS_X = [1, 0.5, -0.5, -1, -0.5, 0.5];
const HEX_CORNERS_Y = [0, 0.866, 0.866, 0, -0.866, -0.866];

function traceHexagonFast(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    ctx.moveTo(HEX_CORNERS_X[0] * r, HEX_CORNERS_Y[0] * r);
    for (let i = 1; i < 6; i++) {
        ctx.lineTo(HEX_CORNERS_X[i] * r, HEX_CORNERS_Y[i] * r);
    }
    ctx.closePath();
}

// Fallback if visual config missing
const DEFAULT_BEAM: BeamVisualDef = {
    type: 'HELIX',
    width: 6,
    coreColor: '#fff',
    glowColor: '#fff'
};

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. Base Position (Int Snapping for Speed)
        ctx.translate(Math.floor(p.x), Math.floor(p.y));

        const now = Date.now() / 1000;

        // 2. Texture Resolution
        if (!p.texture && !p.image && !['PILLAR', 'DOMAIN', 'HEX_BEAM', 'GIANT_HEX', 'GRID_FIELD', 'DEATH_RAY', 'BEAM'].includes(p.type)) {
            if (p.type === 'GLOW' || p.type === 'SPARK' || p.type === 'HEX_GLOW') p.texture = VFXFactory.getTexture('GLOW', p.color);
            else if (p.type === 'SMOKE') p.texture = VFXFactory.getTexture('NOISE', p.color);
            else if (p.type === 'BLAST') p.texture = VFXFactory.getTexture('BLAST', p.color);
            else if (p.type === 'DEBRIS' || p.type === 'ROCK') p.texture = VFXFactory.getTexture('SOLID', p.color);
            else if (p.type === 'HEX_LOCK' || p.type === 'SHOCKWAVE') p.texture = VFXFactory.getTexture('OUTLINE', p.color);

            // New Pre-baked types for performance
            else if (p.type === 'SHARD') p.texture = VFXFactory.getTexture('SHARD', p.color);
            else if (p.type === 'CHIP') p.texture = VFXFactory.getTexture('CHIP', p.color);
        }

        // 3. Render Logic
        if (p.image) {
            ctx.rotate(p.rotation);
            ctx.globalAlpha = 1 - progress;
            const size = Math.floor(p.size);
            ctx.drawImage(p.image, -size/2, -size/2, size, size);
        }
        else if (p.texture) {
            if (p.type === 'SMOKE' || p.type === 'GLOW' || p.type === 'HEX_GLOW') {
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = (1 - progress);
                const scale = p.type === 'SMOKE' ? (1 + progress) : (1 - progress * 0.5);
                ctx.scale(scale, scale);
                ctx.rotate(p.rotation);
                const s2 = p.size * 2;
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            } 
            else if (p.type === 'SPARK') {
                ctx.globalCompositeOperation = 'lighter';
                ctx.rotate(Math.atan2(p.vy, p.vx));
                ctx.scale(Math.min(3, 1 + p.size/10), 0.5);
                ctx.globalAlpha = 1 - progress;
                const s2 = p.size * 2;
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            }
            else {
                ctx.rotate(p.rotation);
                const s2 = p.size * 2;
                // Standard texture draw
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            }
        }
        else {
            this.drawProcedural(ctx, p, progress, isChaos, now);
        }

        ctx.restore();
    },

    drawProcedural(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean, now: number) {

        // --- 1. HEX SHAPES (Hex Beam / Giant Hex) ---
        if (p.type === 'HEX_BEAM' || p.type === 'GIANT_HEX') {
            const def = PROCEDURAL_VISUALS[p.style || ''] || 
                       (p.type === 'HEX_BEAM' ? PROCEDURAL_VISUALS['HEX_CORE'] : PROCEDURAL_VISUALS['HEX_SOLID']);

            ctx.scale(1, ISO_SCALE_Y);
            if (p.type === 'GIANT_HEX') ctx.rotate(p.rotation);
            if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

            if (def.filled) {
                ctx.fillStyle = p.color;
                ctx.globalAlpha = (1 - progress) * (p.type === 'HEX_BEAM' ? 0.9 : 0.8);
                traceHexagonFast(ctx, p.size); ctx.fill();
            }

            if (def.innerScale) {
                ctx.fillStyle = '#fff';
                traceHexagonFast(ctx, p.size * def.innerScale); ctx.fill();
            }

            if (def.stroked) {
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = def.strokeWidth || 2;
                traceHexagonFast(ctx, p.size); ctx.stroke();
            }
        }
        // --- 2. COMPLEX ASSETS (Delegated) ---
        else if (p.type === 'GRID_FIELD') {
            if (p.color === '#be123c' || p.color.includes('blood')) {
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else {
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }
        }
        // --- 3. PILLARS ---
        else if (p.type === 'PILLAR') {
            const def = PROCEDURAL_VISUALS[p.style || ''] || DEFAULT_PILLAR;
            const h = def.height || 1200; 
            const width = p.size * (1 - progress * 0.5) * (def.widthScale || 1.0);

            ctx.save();
            if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

            const grad = ctx.createLinearGradient(0, 0, 0, -h);
            const colBottom = def.gradientBottom === 'current' ? p.color : (def.gradientBottom || p.color);

            grad.addColorStop(0, colBottom);
            grad.addColorStop(0.2, '#fff');
            grad.addColorStop(1, def.gradientTop || 'rgba(0,0,0,0)');

            ctx.fillStyle = grad;
            ctx.globalAlpha = (1 - progress);
            ctx.fillRect(-width/2, -h, width, h);

            if (def.hasBaseRing) {
                ctx.scale(1, ISO_SCALE_Y);
                ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2);
                ctx.strokeStyle = p.color;
                ctx.lineWidth = 3;
                ctx.stroke();
            }

            ctx.restore();
        }
        // --- 4. DOMAINS ---
        else if (p.type === 'DOMAIN') {
            const def = PROCEDURAL_VISUALS[p.style || ''] || PROCEDURAL_VISUALS['DOMAIN_STANDARD'];

            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 

            if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

            const grad = ctx.createRadialGradient(0, 0, r*0.5, 0, 0, r);
            grad.addColorStop(0, 'rgba(0,0,0,0)');
            grad.addColorStop(0.8, p.color);
            grad.addColorStop(1, 'rgba(255,255,255,0.5)');

            ctx.fillStyle = grad;
            ctx.globalAlpha = (def.fillAlpha || 0.3) * (1 - progress);
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            ctx.strokeStyle = def.rimColor || '#ffffff';
            ctx.globalAlpha = 0.15;
            ctx.lineWidth = def.rimWidth || 1;
            if (def.dashed) ctx.setLineDash([10, 10]);
            ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
        // --- 5. BEAMS ---
        else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            if (p.sx !== undefined && p.sy !== undefined && p.sz !== undefined &&
                p.tx !== undefined && p.ty !== undefined && p.tz !== undefined) {

                const styleId = p.style || (p.type === 'DEATH_RAY' ? 'DEATH_RAY' : 'GENERIC_BEAM');
                const conf = BEAM_VISUALS[styleId] || DEFAULT_BEAM;

                const dx = p.tx - p.sx; 
                const startVisY = -UNIT_CHEST_HEIGHT;

                const worldYDelta = p.ty - p.sy;
                const zDelta = p.tz - p.sz;
                const targetVisY = worldYDelta - zDelta - UNIT_CHEST_HEIGHT;

                const dist = Math.sqrt(dx*dx + (targetVisY - startVisY)**2);
                const angle = Math.atan2(targetVisY - startVisY, dx);

                ctx.save();
                ctx.translate(0, startVisY); 
                ctx.rotate(angle);

                // Color Override Logic (Particle Color > Config Color)
                const coreCol = p.color !== '#fff' ? p.color : conf.coreColor;
                const glowCol = p.color !== '#fff' ? p.color : conf.glowColor;
                const width = conf.width * (p.size / 4); // Scale by particle size param

                if (conf.blendMode) ctx.globalCompositeOperation = conf.blendMode;

                if (conf.type === 'HELIX') {
                    const coreWidth = width * Math.sin((1-progress) * Math.PI);
                    if (coreWidth > 0.5) {
                        ctx.strokeStyle = glowCol;
                        ctx.globalAlpha = 0.3 * (1 - progress);
                        ctx.lineWidth = coreWidth * 6;
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                        ctx.globalCompositeOperation = 'lighter';
                        ctx.globalAlpha = 0.8 * (1 - progress);
                        ctx.lineWidth = Math.max(1, coreWidth * 0.8);

                        // Configurable Helix
                        const freq = conf.helixFreq || 0.1; 
                        const amp = (conf.helixAmp || 3) * (width / 4);
                        const speed = now * 20; 
                        const step = 10; 

                        ctx.beginPath();
                        for (let i = 0; i <= dist; i += step) {
                            const yOffset = Math.sin(i * freq - speed) * amp;
                            if (i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
                        }
                        ctx.stroke();

                        ctx.strokeStyle = coreCol;
                        ctx.lineWidth = Math.max(1, coreWidth);
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    }
                } 
                else if (conf.type === 'STRAIGHT' || conf.type === 'VIBRANT') {
                    const w = width * (1 - progress);
                    if (w > 0.5) {
                        // Outer Glow
                        ctx.strokeStyle = glowCol;
                        ctx.shadowColor = glowCol;
                        ctx.shadowBlur = (conf.noiseScale || 0) * 5 + 10;
                        ctx.lineWidth = w * 2;
                        ctx.globalAlpha = 0.6 * (1 - progress);

                        // Jitter for VIBRANT
                        let y1 = 0, y2 = 0;
                        if (conf.noiseScale && conf.noiseScale > 0) {
                            y1 = (Math.random()-0.5) * conf.noiseScale;
                            y2 = (Math.random()-0.5) * conf.noiseScale;
                        }

                        ctx.beginPath(); ctx.moveTo(0,y1); ctx.lineTo(dist, y2); ctx.stroke();
                        ctx.shadowBlur = 0;

                        // Inner Core
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.strokeStyle = coreCol;
                        ctx.lineWidth = w;
                        ctx.globalAlpha = 1.0;
                        ctx.beginPath(); ctx.moveTo(0,y1); ctx.lineTo(dist, y2); ctx.stroke();
                    }
                }

                ctx.restore();
            }
        }
    }
};

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";

const GRAVITY = 1800; 

// Interface for 3D points
interface Point3D { x: number; y: number; z: number; }

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambientTimer: number = 0;

    public reset() {
        this.state.reset();
        this.ambientTimer = 0;
    }

    /**
     * Play a particle effect from the registry
     */
    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride);
    }

    /**
     * Play a beam effect between two points
     */
    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();

        // 3D Anchors
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x;   p.ty = end.y;   p.tz = end.z;

        // Sorting Key (Start Point)
        p.x = start.x; p.y = start.y; p.z = start.z;

        p.life = duration; 
        p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; 
        p.style = styleId; // Generic Style Key
        p.locked = true;

        this.state.particles.push(p);
    }

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // --- V2.0 PHYSICS LOCK ---
            // Locked particles are purely visual/kinematic (controlled by spawner or static)
            if (p.locked) {
                p.rotation += p.vRotation * dt;
                continue; 
            }

            // --- KILL AT TARGET ---
            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX;
                const dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) {
                    p.life = 0; 
                }
            }

            // --- PHYSICS UPDATE ---
            const isPhysical = p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'SPRITE' || p.type === 'ROCK';

            if (isPhysical) {
                let groundH = getTerrainHeight ? getTerrainHeight(p.x, p.y) : 0;

                // Apply Gravity to Z (Height)
                p.vz -= GRAVITY * dt;

                // Integrate
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                // Floor Collision
                if (p.z < groundH) {
                    p.z = groundH;
                    if (Math.abs(p.vz) > 100) {
                        p.vz = -p.vz * 0.5; // Bounce
                        p.vx *= 0.6; 
                        p.vy *= 0.6;
                        p.vRotation *= 0.5;
                    } else {
                        // Resting
                        p.vz = 0;
                        p.vx *= 0.1; 
                        p.vy *= 0.1;
                        p.vRotation = 0;
                        p.z = groundH; // Snap
                    }
                }
            } else {
                // Weightless / Atmospheric
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                if (p.drag !== undefined) {
                    const dragFactor = 1 - p.drag; 
                    p.vx *= dragFactor;
                    p.vy *= dragFactor;
                    p.vz *= dragFactor;
                } else if (p.type === 'SPARK' || p.type === 'SMOKE') {
                    p.vx *= 0.90; 
                    p.vy *= 0.90;
                    p.vz *= 0.90; 
                } else if (p.type === 'GLOW') {
                    // Float
                    p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                    p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
                }
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                this.state.decals.splice(i, 1);
            }
        }

        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;
        this.ambientTimer += dt;
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            const x = Math.random() * 1200 - 100;
            const y = Math.random() * 800 - 100;

            const p = this.state.getParticle();
            p.x = x; p.y = y; p.z = Math.random() * 200 + 50;
            p.type = 'GLOW';

            if (type === 'SNOW') {
                p.color = '#fff';
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 50 + Math.random() * 30;
                p.life = 3.0; p.maxLife = 3.0;
            } else if (type === 'ASH') {
                p.color = '#78350f';
                p.size = Math.random() * 4 + 1;
                p.vx = 30 + Math.random() * 30;
                p.vy = 20 + Math.random() * 20;
                p.life = 4.0; p.maxLife = 4.0;
            } else if (type === 'EMBER') {
                p.color = '#fbbf24';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 20;
                p.vy = -30 - Math.random() * 20;
                p.life = 2.0; p.maxLife = 2.0;
            } else if (type === 'SPORES') {
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 10;
                p.vy = (Math.random() - 0.5) * 10;
                p.life = 5.0; p.maxLife = 5.0;
            }
            this.state.particles.push(p);
        }
    }
}

import { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";

// Helper: Get random number from Range [min, max] or number
const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};

// Helper: Pick random color
const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};

export class VFXPlayer {

    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string) {
        const asset = VFX_REGISTRY[effectId];

        if (!asset) {
            console.warn(`VFXPlayer: Asset '${effectId}' not found.`);
            return;
        }

        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride);
        }
    }

    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string) {
        const count = Math.floor(rnd(config.count));

        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();

            // 1. Position & Velocity Calculation based on Shape
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = cz;
            const speed = rnd(config.speed);

            if (config.shape === 'POINT') {
                // No offset
            } 
            else if (config.shape === 'BURST_DIR') {
                // Omnidirectional Sphere Burst
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);

                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); // Bias upwards slightly
            }
            else if (config.shape === 'CIRCLE') {
                // Flat ring burst
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;

                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }

            // 2. Properties
            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;

            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);

            p.size = rnd(config.size);

            // Color priority: Override > Config
            p.color = colorOverride || pickColor(config.colors);

            // Type Casting (Ensure string matches Particle internal type)
            p.type = config.particleType as any;

            // Apply Visual Style if defined
            if (config.visualStyle) p.style = config.visualStyle;

            // Optional Physics Overrides
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.vRotation) p.vRotation = rnd(config.vRotation);
            else p.vRotation = (Math.random() - 0.5) * 10; // Default gentle rotation

            // Push to System
            system.state.particles.push(p);
        }
    }
}

import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { GameEngine } from "../../game";
import { ULT_VISUALS } from "../../../data/ult_visuals";
import { UNIT_BODY_OFFSET } from "../../../constants";

interface Point3D { x: number; y: number; z: number; }

export class UltArchitect {

    public static play(
        id: string, 
        target: Point3D, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem,
        sourceId?: string
    ): boolean {
        const def = ULT_VISUALS[id];
        if (!def) return false; 

        const { archetype, primaryColor, secondaryColor, scale, count, height, vfxOverride } = def;

        camera.addTrauma(0.3 * scale);

        switch (archetype) {
            case 'HEAVEN_FALL':
                this.playHeavenFall(vfx, target, primaryColor, secondaryColor, height || 1000, scale, vfxOverride);
                break;

            case 'SANCTUARY':
                this.playSanctuary(vfx, target, primaryColor, secondaryColor, count || 6, scale);
                break;

            case 'DOMAIN':
                this.playDomain(vfx, target, primaryColor, secondaryColor, scale, vfxOverride);
                break;

            case 'BEAM_SNIPE':
                this.playBeamSnipe(vfx, engine, grid, target, sourceId, primaryColor, secondaryColor, scale);
                break;

            case 'STORM':
                this.playStorm(vfx, target, primaryColor, secondaryColor, count || 10, scale, vfxOverride);
                break;

            case 'INSTANT_IMPACT':
                this.playInstantImpact(vfx, target, primaryColor, secondaryColor, scale, vfxOverride);
                break;
        }

        return true;
    }

    private static playHeavenFall(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, height: number, scale: number, type?: string) {
        // Falling Object
        const projectile = vfx.state.getParticle();
        projectile.x = target.x; 
        projectile.y = target.y; 
        projectile.z = target.z + height;
        projectile.vx = 0; 
        projectile.vy = 0; 
        const speed = height / 0.4;
        projectile.vz = -speed;
        projectile.life = 0.45; projectile.maxLife = 0.45;
        projectile.color = pColor;
        projectile.size = 100 * scale;
        projectile.type = (type as any) || 'GIANT_HEX'; 
        if (projectile.type === 'GIANT_HEX') projectile.rotation = Math.random() * Math.PI;
        vfx.state.particles.push(projectile);

        // Impact
        setTimeout(() => {
            vfx.playEffect('FX_IMPACT_PHYSICAL', target.x, target.y, target.z, sColor);
        }, 400);
    }

    private static playSanctuary(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, count: number, scale: number) {
        // Center Pillar
        const beacon = vfx.state.getParticle();
        beacon.x = target.x; beacon.y = target.y; beacon.z = target.z;
        beacon.life = 3.0; beacon.maxLife = 3.0;
        beacon.color = pColor; 
        beacon.size = 40 * scale; 
        beacon.type = 'PILLAR'; 
        beacon.locked = true; 
        vfx.state.particles.push(beacon);

        // Surrounding Beams
        const radius = 160 * scale;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const px = target.x + Math.cos(angle) * radius;
            const py = target.y + Math.sin(angle) * radius;
            const start = { x: px, y: py, z: target.z + 10 };
            const end = { x: target.x, y: target.y, z: target.z + 40 };

            // Using New Beam System
            vfx.playBeam('TELEPORT_PILLAR', start, end, sColor, 3.0);
        }
    }

    private static playDomain(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, scale: number, overrideType?: string) {
        // Base Zone
        const zone = vfx.state.getParticle();
        zone.x = target.x; zone.y = target.y; zone.z = target.z;
        zone.life = 4.0; zone.maxLife = 4.0;
        zone.color = pColor; 
        zone.size = 250 * scale;
        zone.type = (overrideType as any) || 'DOMAIN'; 
        zone.locked = true;
        vfx.state.particles.push(zone);

        // Initial Shockwave from generic registry logic (simulated manually here for custom scale)
        const shock = vfx.state.getParticle();
        shock.x = target.x; shock.y = target.y; shock.z = target.z + 5;
        shock.life = 1.5; shock.maxLife = 1.5;
        shock.color = sColor; shock.size = 50 * scale;
        shock.type = 'SHOCKWAVE';
        vfx.state.particles.push(shock);
    }

    private static playBeamSnipe(vfx: VFXSystem, engine: GameEngine, grid: GridSystem, target: Point3D, sourceId: string | undefined, pColor: string, sColor: string, scale: number) {
        if (!sourceId) return;
        const srcAgent = engine.agents.find(a => a.id === sourceId);
        if (!srcAgent) return;

        const terrainH = grid.getTerrainHeight(srcAgent.q, srcAgent.r, engine);
        const srcPt = {
            x: srcAgent.px,
            y: srcAgent.py,
            z: terrainH + srcAgent.physics.z + UNIT_BODY_OFFSET
        };

        if (pColor === '#000') {
             // Railgun
             vfx.playBeam('DEATH_RAY', srcPt, target, undefined, 0.6);
        } else {
             // Generic Snipe
             vfx.playBeam('GENERIC_BEAM', srcPt, target, pColor, 0.6);
        }

        vfx.playEffect('FX_IMPACT_PHYSICAL', target.x, target.y, target.z, sColor);
    }

    private static playStorm(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, count: number, scale: number, overrideType?: string) {
        const radius = 200 * scale;

        for(let i=0; i<count; i++) {
            const p = vfx.state.getParticle();
            const a = Math.random() * Math.PI * 2;
            const r = Math.random() * radius;

            p.x = target.x + Math.cos(a) * r;
            p.y = target.y + Math.sin(a) * r;

            const isRain = overrideType === 'BEAM';

            if (isRain) {
                p.z = target.z + 500;
                p.vx = 0; p.vy = 0; p.vz = -800;
                p.life = 0.6; p.maxLife = 0.6;
                p.type = 'BEAM'; 
                p.style = 'GENERIC_BEAM';
                // Hack: Set target Z far below to create vertical rain beam
                p.sx = p.x; p.sy = p.y; p.sz = p.z;
                p.tx = p.x; p.ty = p.y; p.tz = p.z - 800;
                p.size = 3;
            } else {
                p.z = target.z + Math.random() * 50;
                p.vx = (Math.random()-0.5) * 200;
                p.vy = (Math.random()-0.5) * 200;
                p.vz = 50 + Math.random() * 100;
                p.life = 1.5; p.maxLife = 1.5;
                p.type = (overrideType as any) || 'SMOKE';
                p.size = 15 * scale;
            }

            p.color = Math.random() > 0.5 ? pColor : sColor;
            p.delay = i * 0.05;

            vfx.state.particles.push(p);
        }
    }

    private static playInstantImpact(vfx: VFXSystem, target: Point3D, pColor: string, sColor: string, scale: number, overrideType?: string) {
        if (overrideType === 'GRID_FIELD') {
            vfx.playEffect('FX_GRID_IMPACT_VOID', target.x, target.y, target.z, pColor);
        } else {
            // Manual Explosion for scale control
            // Ideally we'd have Scalable Registry Effects, but for now this works or adding FX_EXPLOSION_LARGE
            vfx.playEffect('FX_IMPACT_PHYSICAL', target.x, target.y, target.z, pColor);
        }
    }
}

