    // World Representation
    overheadType: OverheadEffect; // Animation above head
    floorColor?: string;          // If set, tints the ground tile (e.g. Frozen/Stasis)
    floorOpacity?: number;

    // Model Overrides
    modelOverride?: 'SHEEP' | 'ICE_BLOCK' | 'NONE';
}

