import { createCanvas } from "./CanvasUtils";
import { STATUS_VISUALS } from "../../data/vfx/status_visuals";

const ICON_SIZE = 32;
const STATUS_SIZE = 48;

export const UIFactory = {

    generateSkillIcon(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);

        // Background Frame
        ctx.fillStyle = '#1e293b'; 
        ctx.fillRect(0, 0, ICON_SIZE, ICON_SIZE);

        ctx.strokeStyle = '#334155'; 
        ctx.strokeRect(0, 0, ICON_SIZE, ICON_SIZE);

        // Symbol drawing
        ctx.translate(ICON_SIZE / 2, ICON_SIZE / 2);
        ctx.fillStyle = color;
        ctx.strokeStyle = color;
        ctx.shadowColor = color; 
        ctx.shadowBlur = 5;
        ctx.lineWidth = 2;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';

        ctx.beginPath();
        switch (visual) {
            case 'SLASH': 
                // Slash Arc
                ctx.arc(0, 0, 8, -Math.PI/2, 0);
                ctx.stroke();
                // Blade
                ctx.beginPath(); ctx.moveTo(-8, 8); ctx.lineTo(8, -8); ctx.stroke();
                break;
            case 'ARROW': 
                // Arrow
                ctx.moveTo(-6, 6); ctx.lineTo(6, -6);
                ctx.lineTo(2, -6); ctx.moveTo(6, -6); ctx.lineTo(6, -2);
                ctx.stroke();
                break;
            case 'FIREBALL': 
                // Flame
                ctx.arc(0, 2, 6, 0, Math.PI*2);
                ctx.moveTo(0, -8); ctx.lineTo(0, -4);
                ctx.stroke();
                break;
            case 'BOLT': 
                // Lightning
                ctx.moveTo(2, -8); ctx.lineTo(-4, 0); ctx.lineTo(4, 0); ctx.lineTo(-2, 8);
                ctx.stroke();
                break;
            case 'BEAM': 
                // Laser
                ctx.moveTo(-8, -8); ctx.lineTo(8, 8);
                ctx.moveTo(8, -8); ctx.lineTo(-8, 8);
                ctx.stroke();
                ctx.beginPath(); ctx.arc(0,0,4,0,Math.PI*2); ctx.fill();
                break;
            case 'SMASH': 
                // Hammer
                ctx.rect(-6, -8, 12, 8);
                ctx.moveTo(0, 0); ctx.lineTo(0, 10);
                ctx.stroke();
                break;
            case 'BOMB': 
                // Bomb
                ctx.arc(0, 2, 6, 0, Math.PI*2);
                ctx.stroke();
                ctx.beginPath(); ctx.moveTo(4, -4); ctx.lineTo(8, -8); ctx.stroke();
                break;
            default:
                ctx.arc(0, 0, 6, 0, Math.PI*2);
                ctx.fill();
        }

        return canvas;
    },

    generateStatusIcon(statusId: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(STATUS_SIZE, STATUS_SIZE);
        const cx = STATUS_SIZE / 2;
        const cy = STATUS_SIZE / 2;

        // Load Definition
        const def = STATUS_VISUALS[statusId] || STATUS_VISUALS['DEFAULT'];

        ctx.translate(cx, cy);
        ctx.shadowBlur = 5;
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        // Apply Definition Colors
        ctx.strokeStyle = def.primaryColor;
        ctx.fillStyle = def.primaryColor;
        ctx.shadowColor = def.secondaryColor;

        // Render Shape
        switch (def.iconShape) {
            case 'SPIRAL':
                ctx.beginPath();
                for(let i=0; i<10; i++) {
                    const angle = i * 0.5;
                    const r = 2 + i * 1.5;
                    const x = Math.cos(angle) * r;
                    const y = Math.sin(angle) * r;
                    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
                }
                ctx.stroke();
                break;
            case 'MUTE_BUBBLE':
                ctx.strokeRect(-12, -10, 24, 16);
                ctx.beginPath();
                ctx.moveTo(-6, -2); ctx.lineTo(-6, -2);
                ctx.moveTo(0, -2); ctx.lineTo(0, -2);
                ctx.moveTo(6, -2); ctx.lineTo(6, -2);
                ctx.lineWidth = 4; // dots
                ctx.stroke();
                break;
            case 'SKULL':
                ctx.beginPath(); ctx.arc(0, -2, 10, 0, Math.PI*2); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(-4, 10); ctx.lineTo(4, 10); ctx.stroke();
                break;
            case 'FLAME':
                ctx.beginPath();
                ctx.arc(0, 5, 8, 0, Math.PI*2);
                ctx.moveTo(0, -10); ctx.lineTo(-5, 0); ctx.lineTo(5, 0);
                ctx.fill();
                break;
            case 'CROSS':
                ctx.beginPath();
                ctx.moveTo(0, -10); ctx.lineTo(0, 10);
                ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
                ctx.stroke();
                break;
            case 'GHOST':
                ctx.beginPath();
                ctx.arc(0, -5, 10, Math.PI, 0);
                ctx.lineTo(10, 10);
                ctx.lineTo(5, 5); ctx.lineTo(0, 10);
                ctx.lineTo(-5, 5); ctx.lineTo(-10, 10);
                ctx.closePath();
                ctx.stroke();
                break;
            case 'SHEEP':
                ctx.beginPath();
                ctx.arc(0, 0, 10, 0, Math.PI*2);
                ctx.moveTo(-12, -5); ctx.arc(-8, -5, 4, 0, Math.PI*2);
                ctx.stroke();
                break;
            case 'SHIELD':
                ctx.beginPath();
                ctx.moveTo(-10, -10); ctx.lineTo(10, -10);
                ctx.lineTo(10, 0); ctx.lineTo(0, 12); ctx.lineTo(-10, 0);
                ctx.closePath();
                ctx.fill();
                break;
            default:
                // Circle fallback
                ctx.beginPath(); ctx.arc(0,0,8,0,Math.PI*2); ctx.stroke();
                break;
        }

        return canvas;
    }
};

import { Agent } from "../../game";
import { Team } from "../../../types";
import { HEX_SIZE } from "../../../constants";
import { FACTION_VISUALS } from "../../../data/vfx/faction_visuals";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

// Helper: Local Hexagon Trace
function traceHex(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = i * Math.PI / 3;
        const x = r * Math.cos(angle);
        const y = r * Math.sin(angle);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
}

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    // 1. Load Faction Visual
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.deathSpiritColor; // Reusing spirit color for anchor as it fits the "energy" look

    const feetX = Math.round(physX);
    const feetY = Math.round(physY - physZ); 

    ctx.save();
    ctx.translate(feetX, feetY); // Center at shadow point
    ctx.save();
    ctx.scale(1, 0.58); 
    ctx.lineDashOffset = -t * 20;
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    traceHex(ctx, 18);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();

    if (physZ > 5) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.3;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, physZ); ctx.stroke(); // Vertical line from shadow to body
    }
    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    // 2. Load Faction Visual
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.flightTrailColor;

    ctx.save();
    ctx.translate(0, 5); 
    ctx.scale(1, 0.5); 
    ctx.rotate(t * 8); 
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; 
    // Hexagonal Thruster Ring
    traceHex(ctx, 15);
    ctx.stroke();
    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // --- 1. HEXAGONAL ORBITAL BITS ---
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const orbitRadius = 25;
    for (let i = 0; i < 3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const ox = Math.round(Math.cos(t * 6 + offset) * orbitRadius);
        const oy = Math.round(Math.sin(t * 6 + offset) * orbitRadius * 0.5) - 35;

        ctx.save();
        ctx.translate(ox, oy);
        ctx.rotate(t * 10);
        ctx.beginPath();
        traceHex(ctx, 4 * progress); // Small Hex Bit
        ctx.fillStyle = '#fff';
        ctx.shadowColor = color; ctx.shadowBlur = 10;
        ctx.fill();
        ctx.restore();
    }
    ctx.restore();

    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    ctx.save();
    ctx.translate(0, -40); 
    const scale = 0.5 + progress * 0.5;
    ctx.scale(scale, scale * 0.5); 
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalCompositeOperation = 'screen';
    ctx.rotate(t * 2);
    traceHex(ctx, 60);
    ctx.stroke();
    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -40); 
    const size = Math.round(50 * (0.2 + progress * 0.8));
    ctx.globalCompositeOperation = 'screen';

    // Hexagonal Gradient Fill
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.3;
    traceHex(ctx, size); ctx.fill();

    ctx.fillStyle = '#fff';
    ctx.globalAlpha = 0.5;
    traceHex(ctx, size * 0.6); ctx.fill();

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    ctx.save();
    ctx.translate(Math.round(x), Math.round(y));

    // Calculate size
    const maxPx = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = maxPx * progress;

    ctx.scale(1, 0.58); // Isometric flatten

    // --- LAYER 1: BASE FIELD (Hex Fill) ---
    traceHex(ctx, currentRadius);
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.35; 
    ctx.fill();

    // --- LAYER 2: ENERGY RIM (Hex Glow) ---
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 5;
    ctx.globalAlpha = 0.9;
    ctx.shadowColor = color;
    ctx.shadowBlur = 15;
    traceHex(ctx, currentRadius);
    ctx.stroke();
    ctx.restore();

    // --- LAYER 3: RUNIC BORDER (Rotating Hex) ---
    ctx.save();
    ctx.rotate(t * 1.5); 
    ctx.strokeStyle = '#fff'; 
    ctx.lineWidth = 2;
    ctx.setLineDash([10, 8]); // Dashed pattern
    ctx.globalAlpha = 0.8;
    traceHex(ctx, currentRadius + 2);
    ctx.stroke();
    ctx.restore();

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, Math.round(-110));

            // Hex Glow Background
            ctx.globalAlpha = 0.3 * (0.5 + Math.sin(t * 10) * 0.1);
            ctx.fillStyle = skill.color;
            traceHex(ctx, 40);
            ctx.fill();

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    // Determine active status ID
    let statusId = 'NONE';
    if (agent.banished) statusId = 'BANISH';
    else if (agent.stunTimer > 0) statusId = 'STUN';
    else if (agent.silenceTimer > 0) statusId = 'SILENCE';

    // Fallback if visualStatus override is set
    if (agent.visualStatus !== 'NONE') statusId = agent.visualStatus;

    // Load Definition
    const def = STATUS_VISUALS[statusId];
    if (!def || def.overheadType === 'NONE') return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // Overhead Anchor
    ctx.translate(0, Math.round(-65));

    if (def.overheadType === 'STAR_SPIN') {
        const angle = t * 5;
        const x = Math.round(Math.cos(angle) * 20);
        const y = Math.round(Math.sin(angle) * 6); 
        ctx.fillStyle = def.primaryColor;

        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(t * 10);
        traceHex(ctx, 4);
        ctx.fill();
        ctx.restore();
    } else if (def.overheadType === 'BUBBLE_POP') {
        // Simple pulsing bubble for silence
        const scale = 1 + Math.sin(t * 3) * 0.1;
        ctx.scale(scale, scale);
        ctx.fillStyle = def.primaryColor;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.arc(0, 0, 8, 0, Math.PI*2);
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.stroke();
    } else if (def.overheadType === 'GHOST_FLOAT') {
        const float = Math.sin(t * 2) * 5;
        ctx.translate(0, float);
        ctx.fillStyle = def.primaryColor;
        ctx.globalAlpha = 0.5;
        ctx.beginPath();
        ctx.arc(0, 0, 6, 0, Math.PI*2);
        ctx.fill();
    }

    ctx.restore();
}

import { TerrainRenderer } from "./TerrainRenderer";
import { ZoneRenderer } from "./ZoneRenderer";
import { GroundHazard } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

interface ZoneInfo {
    type: 'CAST';
    color: string;
    visual: string;
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual top Y
        size: number,
        specialStatus: string | undefined,
        zoneInfo: ZoneInfo | undefined,
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined
    ) {
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. HAZARDS (Persistent Ground Effects)
        if (hazard) {
            ZoneRenderer.drawActiveHazard(ctx, x, y, size, hazard, globalTime);
        }

        // 2. SPECIAL STATUS FLOOR EFFECT (Unit State)
        // Data-Driven Floor Tint
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                trace(); 
                ctx.save();
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                ctx.fill(); 
                ctx.restore();
            }
        }

        // 3. ZONE RENDERING (Cast Ripple)
        if (zoneInfo) {
            ZoneRenderer.draw(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.type,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // 4. Dynamic Lighting
        if (lightColor && lightIntensity > 0) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // 5. Interactive Highlights
        if (isRange || isHover || hasUnit) {
            ctx.save();
            trace(); 

            if (isRange) { 
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 1.5; 
                ctx.globalAlpha = 0.6; 
                ctx.stroke();
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.05; 
                ctx.fill();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.1)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.stroke(); 
            }

            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { GameEvent, Team, Role } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import { SpriteManager } from "../../sprites";
import { FACTION_VISUALS } from "../../../data/vfx/faction_visuals";

// Architect
import { UltArchitect } from "./UltArchitect";

// Explicit 3D Point Interface
interface Point3D { x: number; y: number; z: number; }

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine, grid);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine, grid);

        const groundZ = grid.getTerrainHeight(
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).q,
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).r,
            engine
        );

        if (!event.targetId) target.z = groundZ + 20;

        switch (event.type) {
            case 'VISUAL_SLASH':
                if (event.sourceId && event.targetId) {
                    vfx.playBeam('SLASH_CONNECT', origin, target, event.color || '#fff', 0.2);
                }
                break;

            case 'VISUAL_BEAM':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (UltArchitect.play(event.skill.id, target, engine, vfx, grid, camera, event.sourceId)) {
                         return;
                     }
                }
                // Use generic beam logic
                vfx.playBeam('GENERIC_BEAM', origin, target, event.color || '#fff', 0.4);
                vfx.playEffect('FX_IMPACT_PHYSICAL', target.x, target.y, target.z, event.color);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, target);
                }
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, vfx, grid, target, groundZ, camera); 
                } else {
                    vfx.playEffect('FX_IMPACT_PHYSICAL', event.pos.x, event.pos.y, groundZ + 10, event.skill?.color);
                }
                break;

            case 'IMPACT_AOE':
                this.handleAOE(event, engine, vfx, grid, camera, groundZ);
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    // Spawn Manual Unit Parts
                    this.spawnUnitShatter(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                vfx.playEffect('FX_TELEPORT', origin.x, origin.y, origin.z, event.color);
                break;

            case 'CAST_BREAK':
                vfx.playEffect('FX_CAST_BREAK', origin.x, origin.y, origin.z, event.color);
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine, grid: GridSystem): Point3D {
        let agent = agentId ? engine.agents.find(a => a.id === agentId) : null;

        if (!agent && !agentId) {
            const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
            agent = engine.getAgentAt(hex.q, hex.r);
        }

        if (agent) {
            const terrainH = grid.getTerrainHeight(agent.q, agent.r, engine);
            return {
                x: agent.px,
                y: agent.py,
                z: terrainH + agent.physics.z + UNIT_BODY_OFFSET
            };
        }

        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = grid.getTerrainHeight(hex.q, hex.r, engine);

        return {
            x: defaultX,
            y: defaultY,
            z: terrainH 
        };
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, target: Point3D) {
        if (event.skill && event.skill.visualHitEffect) {
            vfx.playEffect(event.skill.visualHitEffect, target.x, target.y, target.z, event.color);
            return;
        }
        // Fallback
        vfx.playEffect('FX_IMPACT_PHYSICAL', target.x, target.y, target.z, event.color || '#94a3b8');
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, target: Point3D, groundZ: number, camera: CameraSystem): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const source = engine.agents.find(a => a.id === event.sourceId);

        if (isUlt && skill) {
            if (UltArchitect.play(skill.id, target, engine, vfx, grid, camera, event.sourceId)) {
                return; 
            }
        }

        if (skill && skill.visualHitEffect) {
            vfx.playEffect(skill.visualHitEffect, target.x, target.y, target.z, color);
            return;
        }

        camera.addTrauma(0.2);

        // Data-Driven Fallback based on Attacker's Faction
        const faction = source ? source.team : Team.BLUE;
        const factionVis = FACTION_VISUALS[faction] || FACTION_VISUALS[Team.BLUE];

        vfx.playEffect(factionVis.defaultHitEffect, target.x, target.y, target.z, color);
    }

    private handleAOE(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, camera: CameraSystem, groundZ: number) {
        if (!event.skill) return;
        const centerPt = { x: event.pos.x, y: event.pos.y, z: groundZ };
        const color = event.color || '#fff';

        if (UltArchitect.play(event.skill.id, centerPt, engine, vfx, grid, camera, event.sourceId)) {
            return;
        }

        if (event.skill.visualHitEffect) {
            vfx.playEffect(event.skill.visualHitEffect, centerPt.x, centerPt.y, centerPt.z, color);
        }

        // GRID SYSTEM REACTION
        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const radius = event.skill.aoeRadius || 1;
        const affectedHexes = HexUtils.range(centerHex, radius);
        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        let gridEffectId = faction === Team.BLUE ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED';
        if (event.skill.ccType === 'PULL' || event.skill.visual === 'BOMB') {
             if (faction === Team.RED) gridEffectId = 'FX_GRID_IMPACT_RED';
        }
        if (event.skill.visual === 'BEAM') gridEffectId = 'FX_GRID_IMPACT_VOID';

        affectedHexes.forEach(h => {
            if (engine.map.isValid(h.q, h.r)) {
                const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                vfx.playEffect(gridEffectId, tilePos.x, tilePos.y, hHeight, color);
            }
        });

        // Center Impact
        vfx.playEffect('FX_IMPACT_PHYSICAL', event.pos.x, event.pos.y, groundZ, event.color);
        camera.addTrauma(0.25); 
    }

    // Logic moved from generic.ts to keep specific sprite logic here
    private spawnUnitShatter(system: VFXSystem, x: number, y: number, z: number, team: Team, role: Role, impulseX: number = 0, impulseY: number = 0) {
        const assets = SpriteManager.getUnitImages(role, team);
        const factionConfig = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];

        // 1. Core Components (Base & Icon)
        const base = system.state.getParticle();
        base.x = x; base.y = y; base.z = z + 10;
        base.vx = impulseX * 0.8; base.vy = impulseY * 0.8;
        base.vz = 150 + Math.random() * 100;
        base.life = 2.0; base.maxLife = 2.0;
        base.color = '#fff'; base.size = 50; 
        base.type = 'SPRITE'; base.image = assets.base;
        base.vRotation = (Math.random() - 0.5) * 10;
        system.state.particles.push(base);

        const icon = system.state.getParticle();
        icon.x = x; icon.y = y; icon.z = z + 40; 
        icon.vx = impulseX * 1.2; icon.vy = impulseY * 1.2;
        icon.vz = 300 + Math.random() * 200;
        icon.life = 2.0; icon.maxLife = 2.0;
        icon.color = '#fff'; icon.size = 64; 
        icon.type = 'SPRITE'; icon.image = assets.icon;
        icon.vRotation = (Math.random() - 0.5) * 20; 
        system.state.particles.push(icon);

        // 2. Data-Driven Shards
        const shardCount = 8;
        const colors = factionConfig.deathShatterColors;

        for(let i=0; i<shardCount; i++) {
            const p = system.state.getParticle();
            p.x = x + (Math.random()-0.5)*20; p.y = y + (Math.random()-0.5)*20; p.z = z + 30;
            const a = Math.random() * Math.PI * 2;
            const s = 150 + Math.random() * 250;
            p.vx = Math.cos(a)*s + impulseX*0.5; p.vy = Math.sin(a)*s + impulseY*0.5; p.vz = 250 + Math.random()*250; 
            p.life = 1.5; p.maxLife = 1.5;
            p.type = 'SHARD'; 
            // Randomly pick a color from the faction palette
            p.color = colors[Math.floor(Math.random() * colors.length)];
            p.size = 6 + Math.random()*8; 
            p.vRotation = (Math.random()-0.5)*30; 
            system.state.particles.push(p);
        }
    }
}

import { GameEvent, GameEventType } from "../../../types";
import { GameEngine } from "../../game";
import { HUDSystem } from "../hud";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { HUD_TEXT_OFFSET, KILL_STREAK_WINDOW } from "../../../constants";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class EventHUDMapper {
    private killStreaks = new Map<string, { count: number, lastTime: number }>();
    private firstBlood = false;

    public reset() {
        this.killStreaks.clear();
        this.firstBlood = false;
    }

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        if (engine.battleTime < 0.1) this.reset();

        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'DAMAGE':
            case 'HEAL':
            case 'CC_APPLIED':
                this.handleCombatText(event, visualGroundY, hud);
                break;
            case 'CAST_START':
                this.handleCastText(event, visualGroundY, hud);
                break;
            case 'KILL':
                this.handleKillStreak(event, engine, grid, hud, camera);
                break;
        }
    }

    private handleCombatText(event: GameEvent, visualY: number, hud: HUDSystem) {
        const baseY = visualY - HUD_TEXT_OFFSET; 
        let text = "";
        let color = "#fff";
        let size = 16;
        let type: 'DAMAGE' | 'HEAL' | 'CC' = 'DAMAGE';
        let xOffset = 0;

        if (event.type === 'DAMAGE') {
            const val = Math.abs(event.value || 0);
            text = val.toString();
            const isCrit = val > 100;

            // 2. TEXT COLORING LOGIC
            const isDot = event.skill?.ccType === 'DOT';

            if (isDot) {
                // Use registered poison color if available, or lime
                color = STATUS_VISUALS['POISON']?.primaryColor || '#a3e635';
            } else if (isCrit) {
                color = '#ef4444'; // Red for Crit
            } else {
                color = '#fff';    // White for normal
            }

            size = isCrit ? 24 : 16;
            type = 'DAMAGE';
            xOffset = (Math.random() - 0.5) * 10;

        } else if (event.type === 'HEAL') {
            text = "+" + Math.abs(event.value || 0);
            color = STATUS_VISUALS['REGEN']?.primaryColor || '#4ade80';
            type = 'HEAL';
            xOffset = (Math.random() - 0.5) * 10;
        } else {
            text = event.text || "";
            color = event.color || "#fff";
            type = 'CC';
            size = 14;
            xOffset = -45;
        }

        if (text) hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
    }

    private handleCastText(event: GameEvent, visualY: number, hud: HUDSystem) {
        if (event.skill && event.skill.tag !== 'BASIC') {
            const isUlt = event.skill.tag === 'ULT';
            const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
            const xOffset = 55; 
            hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
        }
    }

    private handleKillStreak(event: GameEvent, engine: GameEngine, grid: GridSystem, hud: HUDSystem, camera: CameraSystem) {
        if (!event.sourceId) return;

        const now = engine.battleTime;
        const killer = event.sourceId;
        const killerAgent = engine.agents.find(a => a.id === killer);

        if (!killerAgent) return;

        // Visual Position for Streak Text
        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
        const textY = killerAgent.py - kH - HUD_TEXT_OFFSET;

        if (!this.firstBlood) {
            this.firstBlood = true;
            hud.addFloatingText(killerAgent.px, textY - 60, "FIRST BLOOD", "#ef4444", 36, 'KILL_STREAK');
            camera.addTrauma(0.3);
        }

        let streak = 1;
        const existing = this.killStreaks.get(killer);
        if (existing && now - existing.lastTime <= KILL_STREAK_WINDOW) streak = existing.count + 1;

        this.killStreaks.set(killer, { count: streak, lastTime: now });

        if (streak >= 2) {
            let streakText = "DOUBLE KILL";
            let streakColor = "#cbd5e1";

            if (streak === 3) { streakText = "TRIPLE KILL"; streakColor = "#fcd34d"; }
            else if (streak === 4) { streakText = "QUADRA KILL"; streakColor = "#fb923c"; }
            else if (streak >= 5) { streakText = "PENTA KILL"; streakColor = "#ef4444"; }

            hud.addFloatingText(killerAgent.px, textY - 40, streakText, streakColor, 32 + (streak * 4), 'KILL_STREAK');
            camera.addTrauma(0.2 + streak * 0.1);
        }
    }
}

